-- Preserve pre-release authored content for rollback without touching player saves.
create schema if not exists uc_release_backups;
revoke all on schema uc_release_backups from public,anon,authenticated;
create table if not exists uc_release_backups.v50_dialogues as select * from public.campaign_dialogues;
create table if not exists uc_release_backups.v50_chapter_choices as select id,choices from public.campaign_chapters;
create table if not exists uc_release_backups.v50_command_core as select pg_get_functiondef('public.party_command_v30_core(text,text,jsonb)'::regprocedure) as definition;
-- v5.0: server-owned dialogue checks, social consequences, four decisions, optional evidence.
create or replace function public.campaign_novel_dialogue(p_actor bigint,p_state jsonb,p_choice jsonb,p_step int)
returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare s jsonb:=p_state; c jsonb:=p_choice; r jsonb; p public.players%rowtype;
 chapter text:=p_state->>'chapter'; stance text:=p_choice->>'stance'; score int; delta int; rep int;
 n jsonb:=coalesce(p_state->'narrative','{}'); relation jsonb; agency jsonb; skill text:=p_choice->>'skill';
begin
 select * into p from public.players where id=p_actor and user_id=auth.uid();
 if not found then raise exception 'INVALID_ACTOR'; end if;
 if c->>'class' is not null and c->>'class'<>p.class_name then raise exception 'CLASS_DIALOGUE_ONLY'; end if;
 if coalesce((s#>>'{combat,hp}')::int,0)>0 then raise exception 'COMBAT_ACTIVE'; end if;
 relation:=coalesce(n->'relationships','{}'); agency:=coalesce(n->'stances','{}');
 score:=coalesce((relation->>chapter)::int,0);
 if skill is not null then
  r:=public.campaign_v41_dice_core(p_actor,skill,(c->>'dc')::int,'normal',case when score>=3 then 1 when score<=-2 then -1 else 0 end,false)
    ||jsonb_build_object('actor',p.name,'actor_id',p.id,'at',clock_timestamp(),'scope','novel','resolved',true);
  s:=jsonb_set(s,'{last_roll}',r,true);
  if not (r->>'success')::boolean then
   c:=jsonb_set(c,'{reply}',coalesce(c->'failure',to_jsonb('对方没有接受这项要求，但交谈仍可继续。'::text)));
   c:=c||jsonb_build_object('reaction','检定失败：这项要求未被接受，故事继续。','roll',r);
  else
   s:=jsonb_set(s,'{flags}',coalesce(s->'flags','[]')||to_jsonb('n5_pass_'||chapter||'_'||p_step),true);
   c:=c||jsonb_build_object('reaction','检定成功：这项交涉得到回应。','roll',r);
  end if;
 end if;
 delta:=case stance when 'care' then 2 when 'solidarity' then 2 when 'honesty' then 1 when 'public' then 1 when 'humor' then 1 when 'skeptic' then -1 when 'threat' then -2 when 'ruthless' then -2 else 0 end;
 if skill is not null and not (r->>'success')::boolean then delta:=least(delta,0)-1; end if;
 relation:=relation||jsonb_build_object(chapter,greatest(-10,least(10,score+delta)));
 agency:=agency||jsonb_build_object(stance,coalesce((agency->>stance)::int,0)+1);
 n:=n||jsonb_build_object('relationships',relation,'stances',agency);
 s:=s||jsonb_build_object('story_version',5,'narrative',n);
 rep:=case when delta>0 then 1 when delta<0 then -1 else 0 end;
 if rep<>0 then update public.players set reputation=coalesce(reputation,'{}')||jsonb_build_object(c->>'faction',greatest(-100,least(100,coalesce((reputation->>(c->>'faction'))::int,0)+rep))) where id=p_actor; end if;
 if c->>'reaction' is null then c:=c||jsonb_build_object('reaction',case when score+delta>=3 then '合作关系：本场后续交涉检定 +1。' when score+delta<=-2 then '戒备关系：本场后续交涉检定 -1。' else '立场已记入人物关系与派系声望。' end); end if;
 return jsonb_build_object('state',s,'choice',c);
end $$;
revoke all on function public.campaign_novel_dialogue(bigint,jsonb,jsonb,int) from public,anon,authenticated;

create or replace function public.campaign_novel_decision(p_state jsonb,p_choice jsonb,p_index int)
returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare s jsonb:=p_state; c jsonb:=p_choice; ch text:=p_state->>'chapter'; n jsonb:=coalesce(s->'narrative','{}');
begin
 if coalesce((s#>>'{combat,hp}')::int,0)>0 then raise exception 'COMBAT_ACTIVE'; end if;
 -- Legacy clue rewards are not evidence when the optional investigation was skipped.
 if not (coalesce(s->'explored','[]') ? (ch||':0') and coalesce(s->'explored','[]') ? (ch||':1')) then c:=c-'clue'; end if;
 n:=n||jsonb_build_object('decisions',coalesce(n->'decisions','{}')||jsonb_build_object(ch,jsonb_build_object('index',p_index,'label',c->>'label','outcome',c->>'outcome')));
 s:=s||jsonb_build_object('story_version',5,'narrative',n,'last_choice_reply',c->>'outcome');
 return jsonb_build_object('state',s,'choice',c);
end $$;
revoke all on function public.campaign_novel_decision(jsonb,jsonb,int) from public,anon,authenticated;

-- Patch the existing authenticated engine, keeping all combat, rest and retry fixes intact.
do $patch$
declare src text; before text;
begin
 select pg_get_functiondef('public.party_command_v30_core(text,text,jsonb)'::regprocedure) into src;
 if position('campaign_novel_dialogue' in src)=0 then
  before:=src;
  src:=replace(src,'if v_idx not in (0,1) then raise exception ''INVALID_DIALOGUE_CHOICE''; end if;',
   'if v_idx<0 or v_idx>=jsonb_array_length(v_beat->''options'') then raise exception ''INVALID_DIALOGUE_CHOICE''; end if;');
  if src=before then raise exception 'NOVEL_DIALOGUE_PATCH_MISSING'; end if;
  src:=replace(src,'v_choice:=v_beat->''options''->v_idx;',
   'v_choice:=v_beat->''options''->v_idx; v_dialogue:=public.campaign_novel_dialogue(v_id,v_state,v_choice,v_step); v_state:=v_dialogue->''state''; v_choice:=v_dialogue->''choice'';');
  src:=replace(src,'jsonb_build_object(''choice'',v_choice->>''label'',''reply'',v_choice->>''reply'')',
   'jsonb_build_object(''choice'',v_choice->>''label'',''reply'',v_choice->>''reply'',''reaction'',v_choice->>''reaction'',''roll'',v_choice->''roll'')');
  src:=replace(src,'if not (coalesce(v_state->''explored'',''[]''::jsonb) ? ((v_state->>''chapter'')||'':0'')) or not (coalesce(v_state->''explored'',''[]''::jsonb) ? ((v_state->>''chapter'')||'':1'')) then raise exception ''EXPLORE_BEFORE_CHOICE''; end if;',
   'if coalesce((v_state->>''story_version'')::int,0)>=5 then if coalesce((v_state#>>''{dialogue,chapter}'')::int,-1)<>(v_state->>''chapter'')::int or coalesce((v_state#>>''{dialogue,step}'')::int,0)<3 then raise exception ''DIALOGUE_FIRST''; end if; else if not (coalesce(v_state->''explored'',''[]''::jsonb) ? ((v_state->>''chapter'')||'':0'')) or not (coalesce(v_state->''explored'',''[]''::jsonb) ? ((v_state->>''chapter'')||'':1'')) then raise exception ''EXPLORE_BEFORE_CHOICE''; end if; end if;');
  src:=replace(src,'if v_idx<0 or v_idx>1 then raise exception ''INVALID_CHOICE''; end if;','if v_idx<0 then raise exception ''INVALID_CHOICE''; end if;');
  src:=replace(src,'if p_payload is null then raise exception ''INVALID_CHOICE''; end if;',
   'if p_payload is null then raise exception ''INVALID_CHOICE''; end if; v_dialogue:=public.campaign_novel_decision(v_state,p_payload,v_idx); v_state:=v_dialogue->''state''; p_payload:=v_dialogue->''choice'';');
  src:=replace(src,'case when (v_state->''flags'') ? ''council'' then',
   'case when (v_state->''flags'') ? ''n5_choice_28_2'' then ''限期监督改革'' when (v_state->''flags'') ? ''n5_choice_28_3'' then ''各区共同新约'' when (v_state->''flags'') ? ''council'' then');
  src:=replace(src,'f not like ''voice_%'' and','f not like ''n5_%'' and f not like ''voice_%'' and');
  execute src;
 end if;
end $patch$;

-- Hand-authored novel campaign. Existing room history and characters are preserved.
insert into public.campaign_dialogues(chapter_id,speaker,role,beats) values
(0,'守门人哈罗','调查 · 弄清谁把你们列为乘客，并决定哈罗是否值得信任。','[{"text":"哈罗的手还压在剑柄上。车厢里的孩子问：父亲，这次也要关门吗？","options":[{"label":"你听见了什么？先看着我。","reply":"哈罗抬起眼，像从深水里浮上来。“汤米。”他第一次说出那个名字，“我听见他说冷。死的时候，他也只说了这一个字。”","stance":"care","flag":"n5_0_0_0","dc":12,"faction":"merchant"},{"label":"我们的名字为什么在车里？","reply":"“被邀来的人都会有一把椅子。”哈罗擦掉登记簿上的湿墨，你们的名字却又浮了出来，“我只能保证，昨夜这里还没有你们。”","stance":"curiosity","flag":"n5_0_0_1","dc":12,"faction":"merchant"},{"label":"把剑放下。我们一起打开车门。","reply":"他松了松手，却不交剑。“十九年前我也说过一起。其他人走得比我快。”他用肩抵住车门，让你们先站到侧面。","stance":"solidarity","flag":"n5_0_0_2","dc":12,"faction":"merchant"},{"label":"死人不会坐马车。有人在利用你。","reply":"“我知道。”这句回答出乎你们意料。哈罗望着童鞋，“我每天都知道。可我还是想听他再叫一声。”","stance":"skeptic","flag":"n5_0_0_3","dc":12,"faction":"merchant"},{"label":"[威吓] 再挡路，我就当你是同谋。","reply":"哈罗收起剑，拿出城门钥匙。“你可以怀疑我。但先记住谁给你开的门。”他不再替你们遮挡巡灯。","stance":"threat","skill":"威吓","dc":12,"failure":"哈罗把剑插进门缝：“杀我也不会让那辆车说真话。”守卫听见争执，提前接管了路口。","flag":"n5_0_0_4","faction":"merchant"},{"label":"至少这辆车不用排队交过路费。","reply":"哈罗愣了一下，气息终于缓过来。“车费已经有人付了。”他用沾血的手指敲敲登记簿，“问题是，付的不是钱。”","stance":"humor","flag":"n5_0_0_5","dc":12,"faction":"merchant"},{"label":"[战士] 撑住车轴，让哈罗能看清底部。","reply":"你用肩顶住倾斜的车轴。灰烬绕过活人的手，沿车底拼出一行尚未擦净的字；哈罗不再敢说这只是一辆空车。","failure":"车轴滑开，车底的字被泥水抹去。哈罗把你拉回檐下，要求先让车夫下车。","class":"战士","skill":"运动","stance":"solidarity","dc":12,"flag":"n5_class_0_0","faction":"merchant"},{"label":"[游荡者] 比对门闩磨痕，判断谁在事后改册。","reply":"门闩上有两种新磨痕。你指出登记并非在过车时漏写，而是关门后被人重开；哈罗慢慢收回了“我数错了”的解释。","failure":"雨把浅磨痕泡成一道模糊的槽。你无法区分旧损与新伤，不能凭猜测给哈罗定罪。","class":"游荡者","skill":"调查","stance":"curiosity","dc":12,"flag":"n5_class_0_1","faction":"merchant"},{"label":"[法师] 观察灰烬绕开活物的规则。","reply":"你让一片灰靠近掌心，它停在皮肤之外；靠近空椅却贴上木背。被标记的是空缺，尚不能断言所有乘客都死了。","failure":"灰烬在半空散开。你只确认它不是普通炉灰，无法解释空椅与名单的关联。","class":"法师","skill":"奥秘","stance":"curiosity","dc":12,"flag":"n5_class_0_2","faction":"merchant"},{"label":"[牧师] 请哈罗描述记不起的人，而不是背名字。","reply":"他记得那人怕冷、左手提篮，却想不起脸。你把零碎习惯写在姓名栏旁，门楼第一次留住一个没法签字的乘客。","failure":"哈罗把两个夜班的记忆混在一起。他承认疲惫，你留下不同版本，不强行拼出一位证人。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":12,"flag":"n5_class_0_3","faction":"merchant"},{"label":"[游侠] 追踪雨中的车辙与换马位置。","reply":"车辙在门内转向左侧，蹄印却中途换了一组。你指出马车可能换过牵引，不该只凭城外的车夫追究整程责任。","failure":"排水沟冲毁了换马处的浅印。方向仍可查，换马时间暂时不能确定。","class":"游侠","skill":"求生","stance":"curiosity","dc":12,"flag":"n5_class_0_4","faction":"merchant"},{"label":"[吟游诗人] 用数车的小调让门楼众人各唱一遍。","reply":"两名门卫都唱到十二辆，驿夫在第十三节接出了歌词。他没有意识到自己记得，哈罗让他先坐下再慢慢说。","failure":"歌声引来夜巡，驿夫立刻闭嘴。你停下表演，不能把沉默当成否认。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":12,"flag":"n5_class_0_5","faction":"merchant"},{"label":"[圣武士] 要求众人分别见证，不把责任压给一人。","reply":"哈罗把值班者叫到门楼，各自说看见了什么。记录里第一次允许互相矛盾，而不是逼他们挑同一个答案。","failure":"其他门卫拒绝出面。哈罗愿意留下自己的说法，无法保证无人事后改口。","class":"圣武士","skill":"说服","stance":"honesty","dc":12,"flag":"n5_class_0_6","faction":"merchant"}]},{"text":"新班守卫问起车册。哈罗给你们三息时间回答，桌下那只童鞋的鞋尖转向了门内。","options":[{"label":"说我们是来验车的，替哈罗挡住询问。","reply":"你们走到灯下，把最干净的一张纸递过去。哈罗趁机把旧副页塞进你们袖口，守卫却开始记住你们的脸。","stance":"solidarity","flag":"n5_0_1_0","dc":12,"faction":"merchant"},{"label":"让哈罗自己解释，我们不替陌生人作证。","reply":"哈罗报出自己的编号，没有辩解。守卫将他调离门楼；他临走时把童鞋放在你们脚边，像留下一封没写完的信。","stance":"skeptic","flag":"n5_0_1_1","dc":12,"faction":"merchant"},{"label":"[欺骗] 第十三辆车是执政官的机密。","reply":"领班听到执政官三个字便撤开灯。哈罗低声提醒：“以后他们会去问办公室。到时别还站在这个门口。”","stance":"deception","skill":"欺骗","dc":12,"failure":"领班让你们念出文书编号。沉默里，哈罗认下了放行责任，你们失去了他在门楼的掩护。","flag":"n5_0_1_2","faction":"merchant"},{"label":"当众指出：登记簿正在自己写字。","reply":"几名守卫看见墨迹伸出笔画，谁也没有再靠近桌子。街口开始有人围观，你们获得目击者，也失去了悄悄追车的机会。","stance":"public","flag":"n5_0_1_3","dc":12,"faction":"merchant"}]},{"text":"马车开始向城里滑行。哈罗把钥匙推到桌边，却没有看自己的童鞋。","options":[{"label":"追车之前，替他收起那只鞋。","reply":"哈罗没有道谢，只告诉你们寄存铺的位置。“找艾尔。告诉他这次椅子不是空的。”他把那句父亲咽了回去。","stance":"care","flag":"n5_0_2_0","dc":12,"faction":"merchant"},{"label":"只拿钥匙。不答应替他找儿子。","reply":"“这样好。”他像终于可以放松些，“你们不欠我一个死人。只把活着的人带回来。”","stance":"honesty","flag":"n5_0_2_1","dc":12,"faction":"merchant"},{"label":"留下一个假名字，看看契约会不会接受。","reply":"登记簿拒绝你们写下的假名，墨汁聚成一道伤口。哈罗拔下笔尖：“它不认称呼，它认你自己承认的东西。”","stance":"curiosity","flag":"n5_0_2_2","dc":12,"faction":"merchant"},{"label":"告诉街上的人避开这辆车。","reply":"窗后有人拉回了孩子。城门钟没有再响，你们第一次看见警告真正改变了一条街的动作。","stance":"public","flag":"n5_0_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(1,'寄存铺掌柜艾尔','潜入 · 弄清这份名单如何吞掉姓名，并决定是否替艾尔接过十九年的承诺。','[{"text":"白手套在玻璃门上敲了第二下。艾尔把店钥匙塞进嘴里，像宁可吞下去。","options":[{"label":"先躲到柜台后面，剩下的我们应付。","reply":"艾尔摇头：“柜台下面是给孩子藏的。我这把骨头进去，还得劳烦人拆店。”但他的手终于离开了行李袋。","stance":"care","flag":"n5_1_0_0","dc":12,"faction":"merchant"},{"label":"承诺的人叫什么？","reply":"“莉安。”他看着匣子，“不是贵族，不是议员，是给这条街每家孩子量脚的鞋匠。她说名单少一个字，城里就会少一个人。”","stance":"curiosity","flag":"n5_1_0_1","dc":12,"faction":"merchant"},{"label":"你每年收的寄存费从哪里来？","reply":"“匿名汇票。第一年买米，第二年修门，后来我连账都不敢花了。”他拉开抽屉，成捆的汇票上盖着同一枚总钟印。","stance":"skeptic","flag":"n5_1_0_2","dc":12,"faction":"merchant"},{"label":"[欺骗] 我们就是她约好的接头人。","reply":"艾尔观察你们很久，才递来第一年的收据。“她没告诉我接头人长什么样。她说要看他们愿不愿意冒险替别人保管东西。”","stance":"deception","skill":"欺骗","dc":12,"failure":"“她从来没有约接头人。”艾尔按住铜匣。你们仍能检查封蜡，却别想从他这里听见秘密的付款路线。","flag":"n5_1_0_3","faction":"merchant"},{"label":"不妨把匣子给他们，我们保你离城。","reply":"“离城之后呢？我把十九年的自己留在这张柜台上，带走谁？”他的声音不大，门铃却衬得它像在发抖。","stance":"bargain","flag":"n5_1_0_4","dc":12,"faction":"merchant"},{"label":"为什么盖住镜子？怕客人发现你没打扫？","reply":"“怕镜子替我记住客人。”他掀起一角布，镜中柜台上没有铜匣，反而多了一只还没被端走的小鞋。","stance":"humor","flag":"n5_1_0_5","dc":12,"faction":"merchant"}]},{"text":"白手套说只要交出匣子，旧寄存费和你们的姓名都可以一笔勾销。","options":[{"label":"问清楚“勾销姓名”到底意味着什么。","reply":"门外的人笑了：“债务终止，权利也终止。省掉的麻烦比失去的东西多。”艾尔退后一步，告诉你们那就是名单上消失的人。","stance":"skeptic","flag":"n5_1_1_0","dc":12,"faction":"merchant"},{"label":"让艾尔从后门走，我们带匣子吸引他。","reply":"艾尔把收据摆进匣子才走。“别只带名字。带上付过的账。”后门响起轻轻一声，他第一次离开自己守了十九年的柜台。","stance":"care","flag":"n5_1_1_1","dc":12,"faction":"merchant"},{"label":"[威吓] 把手套摘下，让街坊看见你的脸。","reply":"白手套将手放进袖中，露出几乎被墨水染黑的指节。“有些工作不需要脸。”他留下办公室地址后退回雨里。","stance":"threat","skill":"威吓","dc":12,"failure":"他摘下手套，指尖却没有指纹。“很遗憾，威胁不是受理事项。”门口多了两名城卫，你们的出路被迫改到后院。","flag":"n5_1_1_2","faction":"merchant"},{"label":"先答应交易，留下封蜡的拓印。","reply":"你们将一个空匣递向门口，艾尔盖布的手快得让人看不清。真正的名单藏进账簿里，后续调查要有人替这个谎担责。","stance":"deception","flag":"n5_1_1_3","dc":12,"faction":"merchant"}]},{"text":"柜台上只剩那颗乳牙。它旁边的纸条写着：长大以后，别替我签字。","options":[{"label":"把乳牙也带走，它不是证据的垃圾。","reply":"艾尔用干净纸包住它。“莉安没敢带它走。她怕出了城就不记得孩子。”你们第一次理解为什么寄存物比人还难逃。","stance":"care","flag":"n5_1_2_0","dc":12,"faction":"merchant"},{"label":"请艾尔抄一份账，我们不能只信一张名单。","reply":"他一页一页核对付款日，不许你们催。“我的活就是保管。至少这次，我知道自己保管的是谁。”","stance":"curiosity","flag":"n5_1_2_1","dc":12,"faction":"merchant"},{"label":"把空匣留在柜台，让白手套继续找错东西。","reply":"艾尔换掉门上的招牌，将店标作修镜铺。下一位来问遗物的人，要先问他为什么突然改行。","stance":"deception","flag":"n5_1_2_2","dc":12,"faction":"merchant"},{"label":"让街坊知道：有人在买走他们的姓名。","reply":"艾尔递出自己的账册，不肯先躲起来。“那第一笔账得从我开始念。”窗边有人把盖住的镜布拉开。","stance":"public","flag":"n5_1_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(2,'信使诺娅','追逐 · 活着走过屋脊，并决定诺娅还能否成为队伍信任的人。','[{"text":"诺娅把两根绳索系在同一只腕环上。塔里的影子也开始打结。","options":[{"label":"你从哪一封信开始知道出了事？","reply":"“第五封。收信的人问我为什么替陌生人送花。那花是他妻子种的。”诺娅将铜扣藏回袖子，“第六封，我还是送了。”","stance":"skeptic","flag":"n5_2_0_0","dc":12,"faction":"merchant"},{"label":"先把腕环解开，你不是两边的诱饵。","reply":"她想笑，却没能笑出来。“我习惯把退路也绑在自己身上。这样丢东西的时候，就知道是谁弄丢的。”","stance":"care","flag":"n5_2_0_1","dc":12,"faction":"merchant"},{"label":"你弟弟还活着吗？","reply":"“他呼吸着，知道饿，不记得自己叫什么。昨晚开始，他叫我客人。”她望向废塔，“灯里至少还记得他的名字。”","stance":"curiosity","flag":"n5_2_0_2","dc":12,"faction":"merchant"},{"label":"[洞悉] 你在等我们替你做一个不敢做的决定。","reply":"诺娅停止摆弄绳索：“对。如果救他要再送一封信，我怕我还会送。所以我需要有人先看住我的手。”","stance":"honesty","skill":"洞悉","dc":12,"failure":"她把腕环藏起：“你把害怕说成算计，倒也省事。”她仍带路，却不肯再解释弟弟的情况。","flag":"n5_2_0_3","faction":"merchant"},{"label":"救人可以，但把所有送信的地址交出来。","reply":"她立即将一张满是汗渍的纸递来，没有讨价还价。“如果他回来了，我会带他挨家敲门。你们可以跟着。”","stance":"bargain","flag":"n5_2_0_4","dc":12,"faction":"merchant"},{"label":"两根绳索一根都不能断。先救人，再骂你。","reply":"“排队骂吧。”她深吸一口气，“我已经在自己前面排了很久。”然后将最稳的一根绳索交给你们。","stance":"solidarity","flag":"n5_2_0_5","dc":12,"faction":"merchant"}]},{"text":"废塔的蓝灯突然拼出“交出名单”。诺娅手里的纸开始变成空白。","options":[{"label":"让诺娅念出地址，我们替她记。","reply":"她越念越快，最后几个字几乎是在喊。你们的复述使消失的笔画暂时停住；以后调查这些地址时，她得亲自面对收信人。","stance":"solidarity","flag":"n5_2_1_0","dc":12,"faction":"merchant"},{"label":"烧掉地址，切断塔里那东西的追踪。","reply":"纸在火中卷起，蓝灯暗了半拍。你们换得了一段安全路，代价是失去了那些能被追查的门牌。","stance":"ruthless","flag":"n5_2_1_1","dc":12,"faction":"merchant"},{"label":"[奥秘] 对照两座钟楼，找出提前出现的影子。","reply":"你们发现影子跟随的是下一轮钟摆，而非诺娅。调转灯片后，真正的求援位置落在河边，废塔只是他们设下的回声。","stance":"curiosity","skill":"奥秘","dc":12,"failure":"灯片灼破手套，影子开始复制你们的动作。诺娅拉断一根灯线，保住了路线，却让追猎者看清你们的位置。","flag":"n5_2_1_2","faction":"merchant"},{"label":"把名单举到灯下，换弟弟出来。","reply":"诺娅突然抓住你们：“别替我付这个价。我就是这样把别人送进去的。”你们若仍坚持，她会独自回河边照看弟弟。","stance":"bargain","flag":"n5_2_1_3","dc":12,"faction":"merchant"}]},{"text":"追猎者的弩弦已经响过。诺娅问你们能否留下一根绳索给下一批逃出来的人。","options":[{"label":"留绳索，并在另一端点一盏真正的蓝灯。","reply":"她将铜扣钉进横梁。“以后我送信之前，先回来看看这盏灯。”求援的人终于有了一个不需要口令的出口。","stance":"care","flag":"n5_2_2_0","dc":12,"faction":"merchant"},{"label":"只带能带走的人，今晚不再增加风险。","reply":"诺娅割断废塔那根绳。“我会记着这里还有人。你们也记着，别等到别人来提醒。”","stance":"honesty","flag":"n5_2_2_1","dc":12,"faction":"merchant"},{"label":"让诺娅先走，追猎者冲我们来。","reply":"“这次我不会自己跑。”她退到你们身后拉满短弓，第一次没有把活下去误认成逃掉。","stance":"solidarity","flag":"n5_2_2_2","dc":12,"faction":"merchant"},{"label":"给追猎者留一条假灯号。","reply":"红灯指向空钟楼，铁靴声沿错误屋脊远去。诺娅看着你们：“他们回来之前，我们得把真实的灯换掉。”","stance":"deception","flag":"n5_2_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(3,'伊莱娅·维恩','宴会 · 保护仍记得埃弗的人，找到宴会正在掩盖的失踪现场。','[{"text":"伊莱娅把贺卡压在杯底。空椅缓缓转向你们，手套的指尖划过桌布。","options":[{"label":"你为什么让宴会继续？","reply":"“因为楼下有人，楼上的东西就没法假装这屋子从来没有主人。”她敲敲杯子，“一百个人记住同一张椅子，比我一个人守一卷档案有用。”","stance":"curiosity","flag":"n5_3_0_0","dc":12,"faction":"merchant"},{"label":"告诉孩子父亲失踪了，别再演戏。","reply":"“我告诉过。她问父亲是谁。”伊莱娅终于垂下眼，“我能解释死亡，没办法解释一个从来没有活过的人。”","stance":"honesty","flag":"n5_3_0_1","dc":12,"faction":"merchant"},{"label":"先让乐队换一首，不要把所有人困在这里。","reply":"她向琴师递了个手势。第一段新旋律响起，一名老太太忽然想起自己带了生日礼物，抱着盒子哭起来。","stance":"care","flag":"n5_3_0_2","dc":12,"faction":"merchant"},{"label":"[表演] 我替主人敬酒，你趁机带孩子出去。","reply":"你们把笑话讲得很慢，让宾客有时间想起名字。伊莱娅抱起孩子，空手套停在桌布上，像一场即将被揭穿的掌声。","stance":"solidarity","skill":"表演","dc":12,"failure":"宾客问你们与主人有什么关系。楼上那声音抢先喊出答案，伊莱娅不得不留在厅中纠正它。","flag":"n5_3_0_3","faction":"merchant"},{"label":"那个冒充你的东西知道多少？","reply":"“知道我说过的每句话，不知道我没说过的。”她摸着杯口的裂纹，“埃弗逃走那晚，我没告诉他我怕。我想它也不知道。”","stance":"curiosity","flag":"n5_3_0_4","dc":12,"faction":"merchant"},{"label":"生日宴不请主人，确实省了一份礼物。","reply":"她冷冷瞥来，随后把贺卡推近。“你若真想开玩笑，就让孩子笑。她已经整晚在学大人端酒杯了。”","stance":"humor","flag":"n5_3_0_5","dc":12,"faction":"merchant"}]},{"text":"楼上的声音请求开门，自称带回了埃弗的消息。空手套突然落地，露出一个小孩的足印。","options":[{"label":"只问一个伊莱娅从没说出口的问题。","reply":"你们问：埃弗走的那晚，她最怕什么？楼上的声音列举职责、文件和忠诚，始终没有说出“被留下”。伊莱娅自己轻轻答了出来。","stance":"curiosity","flag":"n5_3_1_0","dc":12,"faction":"merchant"},{"label":"让所有宾客看见空手套与足印。","reply":"席间第一次有人不再赞扬主人。有人开始争辩，有人跑出去叫卫队，宴会终于变成一群真实的人在害怕同一件事。","stance":"public","flag":"n5_3_1_1","dc":12,"faction":"merchant"},{"label":"[说服] 请伊莱娅承认她藏起了第二张请柬。","reply":"她从内袋取出请柬，上面邀请的不是你们，是尚未失踪的埃弗。“我怕你们读完就走。”她把它摊平，不再替你们决定该知道多少。","stance":"honesty","skill":"说服","dc":12,"failure":"她收紧袖口：“等查完座次，我们再谈信。”你们没有得到额外线索，但厨师愿意指认送错餐盘的人。","flag":"n5_3_1_2","faction":"merchant"},{"label":"先关住楼梯，送孩子和仆人离开。","reply":"伊莱娅将宴会账交给管家，亲自抱起孩子。最先离席的全是没有收到请柬的人，空椅失去了能替它端盘子的人。","stance":"care","flag":"n5_3_1_3","dc":12,"faction":"merchant"}]},{"text":"琴师等最后一个手势。伊莱娅问：明天的报纸应该写“主人失踪”，还是“宴会照常”？","options":[{"label":"写失踪。让别人知道他需要被找到。","reply":"她在贺卡背面写下埃弗的姓名，交给报童。“别写得体面。写他还有一个等礼物的女儿。”","stance":"public","flag":"n5_3_2_0","dc":12,"faction":"merchant"},{"label":"暂时不登报，先查出是谁代替他签名。","reply":"她拔下座次表上的一根别针，放进你们掌心。“那就给我一个期限。我不会再等十九年。”","stance":"curiosity","flag":"n5_3_2_1","dc":12,"faction":"merchant"},{"label":"让孩子决定贺卡留在哪张椅子上。","reply":"孩子选了靠门的椅子，说那边最容易等到人。伊莱娅没有纠正，你们也没有。","stance":"care","flag":"n5_3_2_2","dc":12,"faction":"merchant"},{"label":"把冒名者引到空主位，别追上楼。","reply":"你们向空椅举杯，楼上的影子开始下行。伊莱娅握紧证词，准备让每一个宾客都看见谁在替主人过生日。","stance":"deception","flag":"n5_3_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(4,'管家赛芙','交易 · 从一张会抹去住户的地图中，救出真实的人与真实的交易记录。','[{"text":"赛芙将汤碗向你们推了推，像在招待最后一次登门的人。","options":[{"label":"你儿子现在在哪里？","reply":"“在院子。他还会觉得饿，所以每天循着味道过来。”她看向门缝，“我不敢告诉他我是母亲，怕他觉得我也是骗子。”","stance":"care","flag":"n5_4_0_0","dc":12,"faction":"merchant"},{"label":"你到底卖掉了多少户？","reply":"她报出二十七，没有少一户。“第一次我拿到的是银子。最后一次，他们让我签儿子的姓。”","stance":"skeptic","flag":"n5_4_0_1","dc":12,"faction":"merchant"},{"label":"这张地图能把人还回来吗？","reply":"“能把门牌还回来。人要自己走回去。”她指着井房，“契约不肯解除买卖，但我还留着撤回交付的钥匙。”","stance":"curiosity","flag":"n5_4_0_2","dc":12,"faction":"merchant"},{"label":"[威吓] 把真图交出来，别再拿儿子作借口。","reply":"她把地图放进你们手里，汤碗却扣住了钥匙。“你们拿到证据了。孩子的事，我自己办。”她不再提供井房的掩护。","stance":"threat","skill":"威吓","dc":12,"failure":"她将两张图同时举向灯火：“逼急一个卖过家的人，很容易再逼出一次。”你们只能先检查井房，不能再指望她辨认真图。","flag":"n5_4_0_3","faction":"merchant"},{"label":"给我钥匙，我把撤回交付的责任签在自己名下。","reply":"赛芙望着你们，半晌才松开碗。“这不一定能救他。它只会让追债的人记住你们。”她把真图的折角摊平。","stance":"solidarity","flag":"n5_4_0_4","dc":12,"faction":"merchant"},{"label":"汤已经凉了。先让孩子吃饭，我们再算账。","reply":"她端着碗出门，没有要求你们起誓。院子里传来勺子敲碗声，你们第一次听到这座宅邸里有人还在吃一顿普通的饭。","stance":"care","flag":"n5_4_0_5","dc":12,"faction":"merchant"},{"label":"[战士] 观察井房是否能支撑住户撤离。","reply":"你把裂梁与出口标在地图边上。赛芙承认井房曾用于紧急疏散，并交代哪一段楼梯承不了多人同时通过。","failure":"梁柱的裂纹伸进墙内，你无法保证整段通道安全。赛芙提供一次单人查路的机会。","class":"战士","skill":"运动","stance":"solidarity","dc":12,"flag":"n5_class_4_0","faction":"merchant"},{"label":"[游荡者] 从新图的折痕找出制图者常看的街区。","reply":"其他街区只是整齐的色块，莉安旧住处旁却有反复折叠留下的破口。制图者知道那里还住着人。","failure":"折痕与搬运损伤混在一起。你不能仅凭一处纸损确定制图者的关注。","class":"游荡者","skill":"调查","stance":"curiosity","dc":12,"flag":"n5_class_4_1","faction":"merchant"},{"label":"[法师] 鉴别图上封印是否约束真正的签字者。","reply":"封印确认的是纸张连续性，既不确认自愿，也不检查住户是否在场。真印能证明纸未换，不能证明售地有效。","failure":"封印残留被井房湿气扰乱。你要求保存原图，避免为尚未确认的效力背书。","class":"法师","skill":"奥秘","stance":"curiosity","dc":12,"flag":"n5_class_4_2","faction":"merchant"},{"label":"[牧师] 询问赛芙照顾过哪些被算为空地的人。","reply":"她报出四户饭量与用药记录。生活细节对上地图上的空地，贵族的“无人居住”有了可核验的反证。","failure":"赛芙仍拒绝说出地址，只留下需要药物的户数。你尊重隐私，不把它写成已核实的人名。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":12,"flag":"n5_class_4_3","faction":"merchant"},{"label":"[游侠] 比较水井使用痕迹与售地日期。","reply":"新绳磨痕在售地后形成，井房那时仍有人取水。地图的空地说法与现场使用记录相冲突。","failure":"绳槽经过维护，时间顺序无法单独确定。你把使用痕迹留作辅证。","class":"游侠","skill":"求生","stance":"curiosity","dc":12,"flag":"n5_class_4_4","faction":"merchant"},{"label":"[吟游诗人] 以售地宣读仪式引出赛芙不敢提的条款。","reply":"你故意读错“自愿交付”，赛芙立刻纠正成“继承承担”。她听过真正的条款，只是一直没敢对住户解释。","failure":"赛芙识破你在试探。她要求先说明原图如何保管，再决定是否开口。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":12,"flag":"n5_class_4_5","faction":"merchant"},{"label":"[圣武士] 让见证人确认同意，拒绝以家族旧债代签。","reply":"赛芙把签名与亲属名单分开。一个死者的签字不能替还活着的住户答应出售；这项异议被写在图背。","failure":"赛芙不肯在雇主回来前签字。你记录她的拒绝，不宣称已取得公证反对。","class":"圣武士","skill":"说服","stance":"honesty","dc":12,"flag":"n5_class_4_6","faction":"merchant"}]},{"text":"井房钥匙上刻着三户门牌。赛芙说可以撤回一张图，但撤回会让买家知道谁违约。","options":[{"label":"撤回交付，并把三户居民都列为见证人。","reply":"赛芙写完最后一个门牌，第一次没有用“空屋”称呼它们。三户人家会被警告，追债人也会知道你们插手了这笔买卖。","stance":"public","flag":"n5_4_1_0","dc":12,"faction":"merchant"},{"label":"用假图替换真图，先让买家以为交易完成。","reply":"她将儿子的房间画进假图的边角，随后又擦掉。“假的东西救不了他，但能让我们多一晚。”","stance":"deception","flag":"n5_4_1_1","dc":12,"faction":"merchant"},{"label":"[调查] 对照汤碗底部，找回地图最早的街线。","reply":"旧街线在油渍下重现，二十七笔交易的先后暴露出来。赛芙指着最早那户：“他们先拿孤寡的人试，因为没人替他们记名字。”","stance":"curiosity","skill":"调查","dc":12,"failure":"汤油洇开了最后一段街线，你们只保住三户门牌。赛芙坚持让你们把那三户先带走，其他交易得去灰市追查。","flag":"n5_4_1_2","faction":"merchant"},{"label":"要求赛芙到街坊面前亲口承认交易。","reply":"她低头整理围裙：“我会去。但我儿子不能跟着。我愿意受他们骂，不愿意让他听见人说卖掉他的母亲。”","stance":"honesty","flag":"n5_4_1_3","dc":12,"faction":"merchant"}]},{"text":"院子里的孩子叫了一声“阿姨”。赛芙应声，脸上没有一丝表情。","options":[{"label":"不催她。等孩子吃完，再走。","reply":"碗底干净得发亮。她把它收进柜里，钥匙交给你们：“现在，告诉我第一户应该怎么道歉。”","stance":"care","flag":"n5_4_2_0","dc":12,"faction":"merchant"},{"label":"告诉她：儿子忘记她，不等于她可以忘记儿子。","reply":"“我没忘。”她抬起头，“我只是一直拿这句话替自己开脱。今晚开始，我不只救一个孩子。”","stance":"honesty","flag":"n5_4_2_1","dc":12,"faction":"merchant"},{"label":"给每一户留下一份地图副本。","reply":"赛芙从储柜拿出描图纸。“我以前画的是售价。你们让我重新写门牌。”她的手仍发抖，却没有画错。","stance":"public","flag":"n5_4_2_2","dc":12,"faction":"merchant"},{"label":"把井房留作撤离出口，下一户可能也需要。","reply":"她取下井盖上的门锁，放在汤碗旁。“这次我不收钥匙。”地下传来缓缓转动的水声。","stance":"solidarity","flag":"n5_4_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(5,'穆雷','对质 · 在真账与假账之间，保住仍靠工资活着的人。','[{"text":"穆雷把一只停摆怀表摆在账本上：“先说好，名字不能给他们。”","options":[{"label":"为什么替已经消失的人发工资？","reply":"“房租还在涨，孩子还得吃。我若只记活得体面的人，修的就不是钟，是刽子手的计时器。”","stance":"care","flag":"n5_5_0_0","dc":12,"faction":"merchant"},{"label":"假账会毁掉你的证词。","reply":"“真账已经毁掉了他们的生活。你们想让我从哪一天开始诚实？”","stance":"skeptic","flag":"n5_5_0_1","dc":12,"faction":"merchant"},{"label":"阿蒙，你妻子最后给你留下了什么？","reply":"他从袋中取出一只左手手套。“右手那只我一直找不到。也许我想起她之前，会先找到它。”","stance":"care","flag":"n5_5_0_2","dc":12,"faction":"merchant"},{"label":"[威吓] 收账人再敲一次，我就卸下他的手。","reply":"阿蒙拦住搬运钩：“别让我们靠你们杀人才能领工钱。”收账人却暂时退开了。","stance":"threat","skill":"威吓","dc":12,"failure":"门被重重撞响。穆雷把账本压入钟架，你们让工人暴露得更早了。","flag":"n5_5_0_3","faction":"merchant"},{"label":"让工人签自愿作证书，不公布家属。","reply":"穆雷给每一页遮住地址，阿蒙率先签名。“我愿意出面，不等于我妻子也欠你们勇敢。”","stance":"solidarity","flag":"n5_5_0_4","dc":12,"faction":"merchant"},{"label":"你这满店钟表，怎么还欠别人时间？","reply":"“因为我修过的钟都会走，欠的时间却只会停。”他仍笑了笑，将怀表递给阿蒙。","stance":"humor","flag":"n5_5_0_5","dc":12,"faction":"merchant"}]},{"text":"收账人提出条件：只收原件，所有工人明天都能正常签工。","options":[{"label":"先抄护送费，给每个工人留工资副本。","reply":"阿蒙把纸分给工友。你们带走的是钱的去向，留下的是他们明天还能讨工资的凭据。","stance":"public","flag":"n5_5_1_0","dc":12,"faction":"merchant"},{"label":"签署保护承诺，名单留在工人手里。","reply":"穆雷卸下钟背的铜片，显出藏账路线。你们保住匿名证人，也承担了往后护送他们的责任。","stance":"solidarity","flag":"n5_5_1_1","dc":12,"faction":"merchant"},{"label":"[欺骗] 用空白账本换原件，假装交付。","reply":"收账人带走钟架里的假账。穆雷开始拆店招牌，知道这场戏迟早会演到自己身上。","stance":"deception","skill":"欺骗","dc":12,"failure":"墨迹在假账上不肯成字。收账人察觉调包，工人必须从后巷撤离。","flag":"n5_5_1_2","faction":"merchant"},{"label":"公布穆雷的假账，包括他自己的责任。","reply":"“别把我洗干净。”穆雷亲自签上姓名，“我希望他们相信，不是只有圣人才肯帮忙。”","stance":"honesty","flag":"n5_5_1_3","dc":12,"faction":"merchant"}]},{"text":"阿蒙找到了右手手套，竟在收账人的口袋里。","options":[{"label":"收好它，别逼阿蒙立刻说感谢。","reply":"他将两只手套叠在一起。你们等到他愿意开口，才得知花房的运水路线。","stance":"care","flag":"n5_5_2_0","dc":12,"faction":"merchant"},{"label":"问收账人为什么拿走这只手套。","reply":"“抵押品。”这两个字让所有工人都停下。你们终于知道契约怎样从一个名字追到一段生活。","stance":"curiosity","flag":"n5_5_2_1","dc":12,"faction":"merchant"},{"label":"把手套交给报社，让城市看见抵押品是什么。","reply":"阿蒙答应，只要求登报之后还给他。他不愿连妻子最后留下的东西也成为公物。","stance":"public","flag":"n5_5_2_2","dc":12,"faction":"merchant"},{"label":"追查拿手套的人，账本交给穆雷守住。","reply":"穆雷修好怀表，把下一次敲门的时间调给你们看。“走吧。这次我把钟拨准。”","stance":"solidarity","flag":"n5_5_2_3","dc":12,"faction":"merchant"}]}]'::jsonb),
(6,'园丁塔姆','救援 · 辨认思念与模仿，阻止更多人用毒水换一个声音。','[{"text":"白蕨忽然叫出米娅的小名。她的剪刀悬在半空。","options":[{"label":"先让米娅把那首歌唱完。","reply":"她唱得断断续续，蕨叶却总抢在她前面。最后一个音停下，她轻轻说：“他从来不抢我的歌。”","stance":"care","flag":"n5_6_0_0","dc":13,"faction":"merchant"},{"label":"塔姆，你知道肥料里是什么吗？","reply":"“知道它能让花长得很快。不知道快的那部分是从谁身上取的。”他摘掉园丁徽章。","stance":"skeptic","flag":"n5_6_0_1","dc":13,"faction":"merchant"},{"label":"不要碰叶子，先隔离水源。","reply":"塔姆关住银桶阀门，窗边的声音逐一暗下。你们保住样本，也让米娅少听见一个熟悉的声音。","stance":"curiosity","flag":"n5_6_0_2","dc":13,"faction":"merchant"},{"label":"[自然] 找出蕨叶正在模仿的规律。","reply":"它只能重复已经听见的句子，没有回答问题的能力。米娅试着问弟弟最怕什么，花房只重复了回家。","stance":"honesty","skill":"自然","dc":13,"failure":"花粉模糊了你们的听觉。塔姆将样本装瓶，提醒去盐井才能查清它真正的来源。","flag":"n5_6_0_3","faction":"merchant"},{"label":"这些花归谁所有？我们要带走样本。","reply":"“屋主所有，声音不是。”塔姆把最小一株连盆交来，不肯收钱。","stance":"bargain","flag":"n5_6_0_4","dc":13,"faction":"merchant"},{"label":"如果它唱走调，你弟弟会不会嫌它？","reply":"米娅抹了抹脸：“会。他比我还难听，偏要纠正我。”她终于放下了剪刀。","stance":"humor","flag":"n5_6_0_5","dc":13,"faction":"merchant"}]},{"text":"宅邸管事要烧掉花房，称所有声音都是危险的幻觉。","options":[{"label":"带走样本，要求留下出库编号。","reply":"管事撕掉送货簿，塔姆却从桶底取出铜牌。样本与签发人终于能被放在同一张证词上。","stance":"curiosity","flag":"n5_6_1_0","dc":13,"faction":"merchant"},{"label":"先带学徒离开，不让她为花作证。","reply":"米娅将剪刀交给塔姆。“你来剪。我想记住他唱过歌，不想记住我怎样杀掉它。”","stance":"care","flag":"n5_6_1_1","dc":13,"faction":"merchant"},{"label":"[说服] 让管事承认焚毁命令来自谁。","reply":"管事报出总钟维护处的印号，还坚持自己只负责花。塔姆要求把这句话也记录下来。","stance":"honesty","skill":"说服","dc":13,"failure":"管事不肯落款，你们只能带走桶牌，不能拿这份供词指认更高的责任人。","flag":"n5_6_1_2","faction":"merchant"},{"label":"允许销毁白蕨，但先封住排水道。","reply":"声音在火中停了，黑色结晶留在水槽里。你们失去活体样本，避免了毒水继续流向工人街。","stance":"ruthless","flag":"n5_6_1_3","dc":13,"faction":"merchant"}]},{"text":"米娅问你们：找到弟弟以后，能不能别再让他唱这首歌？","options":[{"label":"可以。他不欠任何人一次重演。","reply":"她收起空花盆，说准备先学一首新歌。塔姆给了她离城的工资，没再从中扣掉盆钱。","stance":"care","flag":"n5_6_2_0","dc":13,"faction":"merchant"},{"label":"我们能答应寻找，不能保证找到。","reply":"她点头：“至少你们没有像花那样，只说我想听见的。”","stance":"honesty","flag":"n5_6_2_1","dc":13,"faction":"merchant"},{"label":"请她保留桶牌，在安全地方作证。","reply":"她在铜牌背面写下自己的名字，要你们先读一遍，确认笔画没有消失。","stance":"solidarity","flag":"n5_6_2_2","dc":13,"faction":"merchant"},{"label":"把出库号寄给编辑，别只留一份。","reply":"报社收到第一封没有遗言的信，信里是仍活着的人在要求调查。","stance":"public","flag":"n5_6_2_3","dc":13,"faction":"merchant"}]}]'::jsonb),
(7,'报社编辑莉缇','新闻 · 决定让城市读到什么，以及谁来承担公开真相的代价。','[{"text":"印机正在预热。莉缇用指甲划过三处相同的错字。","options":[{"label":"他为什么写了三封相互矛盾的信？","reply":"“他想让家人逃，让报社闭嘴，让街坊原谅。三件事做不到一起，就写成了三个人。”她第一次没有替他辩护。","stance":"skeptic","flag":"n5_7_0_0","dc":13,"faction":"merchant"},{"label":"先让薇拉离开机器，再谈截稿。","reply":"薇拉不肯丢下铅字。你们帮她抱出来，桌面上一整段被改写的求救终于排成原句。","stance":"care","flag":"n5_7_0_1","dc":13,"faction":"merchant"},{"label":"谁在最后一分钟换掉了末句？","reply":"莉缇递来军需仓支票：“有人以广告费买下了最后一个句号。他们不需要删整封信。”","stance":"curiosity","flag":"n5_7_0_2","dc":13,"faction":"merchant"},{"label":"[调查] 找出三封信共同留下的暗记。","reply":"三封信在不同位置省去了同一个人名。省略的空位连在一起，正好是那位被抹去的鞋匠。","stance":"curiosity","skill":"调查","dc":13,"failure":"你们只能确认最后一段换过纸，无法确认埃弗自己留下的暗记。薇拉愿意保管原版等待复核。","flag":"n5_7_0_3","faction":"merchant"},{"label":"公布他售地的承认，别替他洗清。","reply":"“我不替他洗。”莉缇将家人地址从稿上划去，“但孩子也不替他担罪。”","stance":"public","flag":"n5_7_0_4","dc":13,"faction":"merchant"},{"label":"三封都登，让他回来自己解释。","reply":"薇拉从机房笑了一声：“那就加一页。今晚终于不是拿别人的结尾省纸了。”","stance":"honesty","flag":"n5_7_0_5","dc":13,"faction":"merchant"}]},{"text":"报童已经在门口等。卫队的封条被钉在招牌下面。","options":[{"label":"先登原版求救，暂时遮住收信人的住址。","reply":"莉缇加上说明：其余两封正在核实。你们救下一批可能被追查的家属，也让报社承受了公开质疑。","stance":"care","flag":"n5_7_1_0","dc":13,"faction":"merchant"},{"label":"三封并列，把改动痕迹一同印出来。","reply":"读者将看到不同结尾，不能只挑自己想相信的那一封。莉缇签名承担报道责任。","stance":"public","flag":"n5_7_1_1","dc":13,"faction":"merchant"},{"label":"[欺骗] 将原版藏入广告栏，表面照旧付印。","reply":"薇拉把求救拆进三条寻物启事。卫队带走头版，街坊却会在卖鞋的广告里看见缺失的名字。","stance":"deception","skill":"欺骗","dc":13,"failure":"审稿人发现铅字字重不符，印机被停。莉缇抢下排样，你们得亲自将消息送到夜巡队。","flag":"n5_7_1_2","faction":"merchant"},{"label":"不付印，带原信走。","reply":"莉缇按下停机柄：“今晚我们可以闭嘴，但不要把闭嘴叫作中立。”报童散去，城中少了一次公开追问。","stance":"skeptic","flag":"n5_7_1_3","dc":13,"faction":"merchant"}]},{"text":"薇拉在废铅字里找到一个完整的“活”字，递给你们。","options":[{"label":"让报童把活字印在最后一张纸上。","reply":"她给那张纸添上名字：埃弗。今夜的报道不保证他无罪，只保证城市还会找他。","stance":"public","flag":"n5_7_2_0","dc":13,"faction":"merchant"},{"label":"替她写一份保管原信的收据。","reply":"“不是怕你们偷。”她把收据折好，“怕明天有人告诉我，我从来没有拿过它。”","stance":"solidarity","flag":"n5_7_2_1","dc":13,"faction":"merchant"},{"label":"给报社留一条撤离路线。","reply":"莉缇看了看机器，最后只背上排样。“印机可以重买。愿意把字排出来的人不能。”","stance":"care","flag":"n5_7_2_2","dc":13,"faction":"merchant"},{"label":"追查买句号的支票，不先追埃弗。","reply":"军需仓编号指向夜巡队。真正的故事从誰能改写结尾，变成谁能命令别人相信它。","stance":"curiosity","flag":"n5_7_2_3","dc":13,"faction":"merchant"}]}]'::jsonb),
(8,'夜巡队长维斯','对质 · 拆穿假制服，也决定真正的队长怎样承担罪责。','[{"text":"维斯不让你们碰尸体的脸：“他没做错事。别让死的人也替活人挨一次打。”","options":[{"label":"为什么签假到？","reply":"“他女儿问我为什么父亲每天换姓。我答不出，就把那天的签名留住了。”","stance":"care","flag":"n5_8_0_0","dc":13,"faction":"guard"},{"label":"死人到底是谁？","reply":"“登记册写的是活人，尸体只负责让清账合理。你们找到名字之前，我不会把他埋成证据。”","stance":"curiosity","flag":"n5_8_0_1","dc":13,"faction":"guard"},{"label":"你替谁执行过清账命令？","reply":"维斯摘下队长章：“三个人。不是三次误会，是三个人。”","stance":"skeptic","flag":"n5_8_0_2","dc":13,"faction":"guard"},{"label":"[威吓] 不说发令者，就把章交出去。","reply":"他报出军需官姓名，把章也留下。“我不会再让部下替我签名。”","stance":"threat","skill":"威吓","dc":13,"failure":"他要求依法立案，假夜巡趁争执向茶摊靠近。","flag":"n5_8_0_3","faction":"guard"},{"label":"我们先救孩子，再谈你的责任。","reply":"维斯让费托带孩子走，自己站到假夜巡能看见的街口。","stance":"solidarity","flag":"n5_8_0_4","dc":13,"faction":"guard"},{"label":"以后签到表加上画像，也许能少认错一次。","reply":"“画像会淡。我需要人记得。”他给你们看那名士兵女儿画的歪脸。","stance":"humor","flag":"n5_8_0_5","dc":13,"faction":"guard"}]},{"text":"假巡逻队递来拘捕令，要求你们协助逮捕画中的逃兵。","options":[{"label":"核对原件，拒绝只凭队长的说法。","reply":"维斯交出两份编号相同的命令。真假之争第一次有了纸面的缺口。","stance":"curiosity","flag":"n5_8_1_0","dc":13,"faction":"guard"},{"label":"公开护送士兵离开茶摊。","reply":"孩子认出父亲，假巡逻队却要求她证明亲属关系。整条街开始替她回答。","stance":"public","flag":"n5_8_1_1","dc":13,"faction":"guard"},{"label":"[说服] 让新兵先放下武器，听孩子说完。","reply":"新兵后退一步，没有转身攻击上级，只拒绝把枪口对准父女。","stance":"care","skill":"说服","dc":13,"failure":"新兵不敢抗令，你们必须承担掩护父女撤离的战斗。","flag":"n5_8_1_2","faction":"guard"},{"label":"交出维斯，换士兵撤销叛逃。","reply":"维斯同意换人，孩子却问为什么做好事的人总要留下。","stance":"bargain","flag":"n5_8_1_3","dc":13,"faction":"guard"}]},{"text":"维斯把队长章放到孩子手里，让她画一个她认得的父亲。","options":[{"label":"留下真实的签名与画像。","reply":"士兵按下手印，不再借假姓活下去。他将亲自到听证会作证。","stance":"honesty","flag":"n5_8_2_0","dc":13,"faction":"guard"},{"label":"先让父女走，签名以后再补。","reply":"维斯记住他们离开的方向，承认安全比完整的手续更重要。","stance":"care","flag":"n5_8_2_1","dc":13,"faction":"guard"},{"label":"让维斯对三名死者逐一作证。","reply":"他没有拿救人的事抵罪，从第一份命令开始口述。","stance":"skeptic","flag":"n5_8_2_2","dc":13,"faction":"guard"},{"label":"将同号军令送到街坊会。","reply":"卫队不再能单独决定哪一份军令算数。","stance":"public","flag":"n5_8_2_3","dc":13,"faction":"guard"}]}]'::jsonb),
(9,'街坊代表阿黛','集会 · 让一条街参与自己的命运，不把它写成英雄的背景。','[{"text":"阿黛将地契铺在板凳上：“你们有武器。我们有明天要交的房租。谁更急？”","options":[{"label":"你希望明天先改变什么？","reply":"“房东敲门时，我们能要求他解释，而不是求他可怜。”","stance":"care","flag":"n5_9_0_0","dc":13,"faction":"guard"},{"label":"旧议会为什么驱逐你的丈夫？","reply":"“因为他说租地的人也该投票。别把旧制度写得比旧人干净。”","stance":"skeptic","flag":"n5_9_0_1","dc":13,"faction":"guard"},{"label":"印章能证明哪一条交易无效？","reply":"她指着缺口：“只能证明有人伪造，不能证明所有盖过真章的人都善良。”","stance":"curiosity","flag":"n5_9_0_2","dc":13,"faction":"guard"},{"label":"[历史] 让修补年月与驱逐日期对照。","reply":"纪念碑修补正发生在驱逐后，伪地契试图将那批住户的存在抹到更早。","stance":"curiosity","skill":"历史","dc":13,"failure":"碑文损坏得太重，你们只能保留拓片，必须再找登记处核对。","flag":"n5_9_0_3","faction":"guard"},{"label":"我不答应恢复旧议会，只答应让你们旁听。","reply":"阿黛移开板凳，给你们留出门边的位置。“那先兑现这个。”","stance":"honesty","flag":"n5_9_0_4","dc":13,"faction":"guard"},{"label":"这板凳比贵族宴会的椅子踏实。","reply":"“摔下来也没那么丢人。”屋里第一次有人愿意递茶。","stance":"humor","flag":"n5_9_0_5","dc":13,"faction":"guard"}]},{"text":"石匠带来裂章拓片，阿黛却先把被驱逐者的名单推到最前面。","options":[{"label":"先核验拓片，不提前宣布胜利。","reply":"居民留下名字等待复核。你们获得的是证人，不是随叫随到的掌声。","stance":"curiosity","flag":"n5_9_1_0","dc":13,"faction":"guard"},{"label":"给每户讲清地契问题，避免承诺立刻退租。","reply":"阿黛亲自解释哪些能确认、哪些还不能，争论没有停止，但谣言少了。","stance":"honesty","flag":"n5_9_1_1","dc":13,"faction":"guard"},{"label":"[说服] 说服各户共同保管证据副本。","reply":"拓片被分藏在四个厨房，卫队查封一间屋也没法封掉整条街的记忆。","stance":"solidarity","skill":"说服","dc":13,"failure":"有住户怕被报复。阿黛自己留下原片，不允许你们把害怕写成背叛。","flag":"n5_9_1_2","faction":"guard"},{"label":"允许拆碑，把原刻留下作为证物。","reply":"碑倒下时没人欢呼。阿黛带走刻着丈夫工号的石块，终于不再经过它假装没看见。","stance":"ruthless","flag":"n5_9_1_3","dc":13,"faction":"guard"}]},{"text":"阿黛问你们，新的章该由谁保管。","options":[{"label":"居民轮流保管，不给任何人永久钥匙。","reply":"她写下轮值表，要你们也遵守同一条规则。","stance":"public","flag":"n5_9_2_0","dc":13,"faction":"guard"},{"label":"调查结束前封存，不把证据变成权杖。","reply":"石匠盖好匣子，承诺每次启封都有两名居民在场。","stance":"honesty","flag":"n5_9_2_1","dc":13,"faction":"guard"},{"label":"留一枚裂章，提醒后来者旧错仍在。","reply":"阿黛将裂口朝上：“不要修得像什么都没发生。”","stance":"care","flag":"n5_9_2_2","dc":13,"faction":"guard"},{"label":"把租户名单一起带到拍卖场。","reply":"她为你们写出一个价格：每个空地名下，至少有一个活人。","stance":"solidarity","flag":"n5_9_2_3","dc":13,"faction":"guard"}]}]'::jsonb),
(10,'拍卖师兰恩','拍卖 · 从被出售的权利中，夺回说“不”的资格。','[{"text":"兰恩举着拍槌，等待你们否认台上的姓名。","options":[{"label":"我不承认任何人有权出售它。","reply":"“那请别否认自己。”他提醒，“你一旦说那个名字不是你的，他们就替你做完退场了。”","stance":"honesty","flag":"n5_10_0_0","dc":13,"faction":"guard"},{"label":"是谁替我们付的保证金？","reply":"他看向遮面包厢：“办公室不来人，只来钱。账房保管付款路径。”","stance":"curiosity","flag":"n5_10_0_1","dc":13,"faction":"guard"},{"label":"你妻子签字时，你在场吗？","reply":"“我拿着她买的生日酒。她说想轻松一点，我以为只是想辞职。”","stance":"care","flag":"n5_10_0_2","dc":13,"faction":"guard"},{"label":"[表演] 当众给自己的名字标一个没人付得起的价格。","reply":"台下的竞价开始变成笑声。兰恩故意放慢拍槌，让你们争取到进后台的时间。","stance":"humor","skill":"表演","dc":13,"failure":"包厢报出更高价格，观众当成好戏。兰恩示意你们赶紧去后台，别让笑声盖住成交。","flag":"n5_10_0_3","faction":"guard"},{"label":"我可以买下其他人的退场书吗？","reply":"“你买到的是他们的沉默，不是他们的同意。”兰恩把妻子的空书推来。","stance":"bargain","flag":"n5_10_0_4","dc":13,"faction":"guard"},{"label":"取消拍卖，否则我先拆你的台。","reply":"他放下拍槌：“我也想听它碎一次。但后台还有人抵着账房的门。”","stance":"threat","flag":"n5_10_0_5","dc":13,"faction":"guard"},{"label":"[战士] 从保安站位找出不会挟住拍品持有人的出口。","reply":"两名保安都挡着贵宾席，后场送货门只有一人。你让持有人知道那条路，拍卖师第一次失去垄断撤离的筹码。","failure":"保安提前封门。你仍能护住身边的人，却不能承诺整排拍品都能离场。","class":"战士","skill":"运动","stance":"solidarity","dc":13,"flag":"n5_class_10_0","faction":"guard"},{"label":"[游荡者] 把保证金收据与座号交换的顺序对上。","reply":"收据在买家入场前已签，座号随后才换成你们的名字。假身份是担保人安排的，不能只抓面具买家结案。","failure":"收据副页被抽走。你得到一处账目缺口，尚未确认安排换号的人。","class":"游荡者","skill":"调查","stance":"curiosity","dc":13,"flag":"n5_class_10_1","faction":"guard"},{"label":"[法师] 检验名签是否能强迫主人履约。","reply":"名签只是一道识别索引，真正的束缚藏在拍品附页。撕名签能打乱登记，却不能替受害者解除契约。","failure":"索引反馈被兰恩的屏障截断。你停止施术，避免误触附页上的承诺。","class":"法师","skill":"奥秘","stance":"curiosity","dc":13,"flag":"n5_class_10_2","faction":"guard"},{"label":"[牧师] 辨认买家是惊慌还是在诱导英雄代付。","reply":"她看向保安而不是拍品，先问你们是否愿意替别人签字。你指出救人不能以英雄接手抵押为条件。","failure":"面具遮住了关键反应。你直接拒绝代签，不能断言她的动机。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":13,"flag":"n5_class_10_3","faction":"guard"},{"label":"[游侠] 从货箱绳结判断原件何时进入会场。","reply":"河运绳结还湿，保证金账却在三天前开出。卖方先出售了承诺，今天才设法拿到能兑现它的原件。","failure":"货箱重新绑过，来源线索被混淆。你只记录发现的河泥，不擅定抵达日期。","class":"游侠","skill":"求生","stance":"curiosity","dc":13,"flag":"n5_class_10_4","faction":"guard"},{"label":"[吟游诗人] 临时竞价，把掌声转成对规则的质问。","reply":"你问下一轮是否拍卖前排观众的姓名，笑声变成一阵核对。兰恩无法再把索取同意说成破坏气氛。","failure":"前排买家压住笑声。兰恩请你付竞价保证金；你退出竞价，保留公开反对。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":13,"flag":"n5_class_10_5","faction":"guard"},{"label":"[圣武士] 要求撤回资格必须与买入资格同等公开。","reply":"拍品持有人站起来问能否拒绝被售出，其他席位不得不回答。拒绝不再是一条只写在后台的例外。","failure":"兰恩拒绝临时改规。持有人已听见撤回要求，却尚未获得安全离场保证。","class":"圣武士","skill":"说服","stance":"honesty","dc":13,"flag":"n5_class_10_6","faction":"guard"}]},{"text":"伊曼握着保证金凭证，门外的护卫要求继续成交。","options":[{"label":"潜入后台，保留账户与付款时刻。","reply":"你们取出的是资金链，没替任何被拍卖者签下一份新纸。","stance":"curiosity","flag":"n5_10_1_0","dc":13,"faction":"guard"},{"label":"与买家交涉，拖到其他拍品撤离。","reply":"兰恩故意念错金额，退场的人第一次不用向拍卖师道谢。","stance":"bargain","flag":"n5_10_1_1","dc":13,"faction":"guard"},{"label":"[威吓] 让护卫向观众出示逮捕依据。","reply":"护卫没有文书。最先离席的是那些以为花钱就能买合法权利的人。","stance":"public","skill":"威吓","dc":13,"failure":"护卫封住后台出口，伊曼只能交出副本，原件仍在买家手里。","flag":"n5_10_1_2","faction":"guard"},{"label":"毁掉拍品，但不烧付款凭证。","reply":"姓名在火边重新浮起，账房用湿布保住每一个付款人的签名。","stance":"ruthless","flag":"n5_10_1_3","dc":13,"faction":"guard"}]},{"text":"兰恩留下妻子的退场书，问是否应该把她的生日写回去。","options":[{"label":"写回去，也许她会找到这个地址。","reply":"他用最好的墨写日期，没有把寻找她的责任交给你们。","stance":"care","flag":"n5_10_2_0","dc":13,"faction":"guard"},{"label":"先公开拍卖规则，别只救今天的客人。","reply":"伊曼开始抄写作废条件，市民终于有一份能看懂的退场书。","stance":"public","flag":"n5_10_2_1","dc":13,"faction":"guard"},{"label":"让账房带原件走，不把他留给买家。","reply":"兰恩将后台门推开，亲自站在拍卖台上解释散场。","stance":"solidarity","flag":"n5_10_2_2","dc":13,"faction":"guard"},{"label":"保留一次假成交，追到付款账户。","reply":"拍槌最后落下一次，敲给一个已经没有拍品的包厢。","stance":"deception","flag":"n5_10_2_3","dc":13,"faction":"guard"}]}]'::jsonb),
(11,'守塔人格雷','抢救 · 不让拿到证据的胜利，建立在井下居民的灾难上。','[{"text":"格雷拿着断齿的扳手，不知道该对准机械还是你们。","options":[{"label":"先告诉我们侧井会发生什么。","reply":"“不是水，是没被城市处理完的废液。它一直往下流，钟替上面的人算着还能多流多久。”","stance":"curiosity","flag":"n5_11_0_0","dc":13,"faction":"guard"},{"label":"你妻子知道你拿她的街道保钟吗？","reply":"“她叫我回来吃饭。我没敢告诉她，我一回家，整条街就得搬。”","stance":"skeptic","flag":"n5_11_0_1","dc":13,"faction":"guard"},{"label":"找第二个承压点，不能只谈停或不停。","reply":"萝丝掀开旧图，露出从未接入的备用发条。原来的设计并不需要井下的人付费。","stance":"curiosity","flag":"n5_11_0_2","dc":13,"faction":"guard"},{"label":"[奥秘] 解析安全休眠的齿序。","reply":"你们让一台机械暂眠，抽出备用发条，获得不切断承压的检修间隙。","stance":"solidarity","skill":"奥秘","dc":13,"failure":"休眠失败，机械继续封住齿箱。萝丝改用手动支撑，为你们保住取纸的最后机会。","flag":"n5_11_0_3","faction":"guard"},{"label":"把井下居民先撤离，再停钟。","reply":"格雷报出妻子所在的街名，终于肯接受别人也可以承担救人的工作。","stance":"care","flag":"n5_11_0_4","dc":13,"faction":"guard"},{"label":"这么多人维护，谁负责修那句“临时”？","reply":"萝丝扔掉旧交接表：“今晚轮到我改。”","stance":"humor","flag":"n5_11_0_5","dc":13,"faction":"guard"}]},{"text":"齿箱开始切入纸边。萝丝要你们选择先扶发条，还是先取契约。","options":[{"label":"托住发条，纸页可以少半边。","reply":"机器停下半拍，格雷接住残纸。你们保住井下，失去部分原条款，往后需要额外证词补足。","stance":"care","flag":"n5_11_1_0","dc":13,"faction":"guard"},{"label":"取出纸页，再让格雷手动承压。","reply":"他抱住扳手，答应撑到居民撤离；这个承诺会耗尽他最后的力气。","stance":"ruthless","flag":"n5_11_1_1","dc":13,"faction":"guard"},{"label":"[运动] 扛起齿箱，为两边争取空间。","reply":"萝丝楔入支撑，契约与备用发条都被取出。格雷放开手时几乎站不起来。","stance":"solidarity","skill":"运动","dc":13,"failure":"齿箱压回，萝丝先救你们的手。纸页仍被救出，备用发条却断在箱内。","flag":"n5_11_1_2","faction":"guard"},{"label":"让机械继续运行，记下残页而不取原件。","reply":"格雷接受抄本，但提醒真伪争议会留到公证席。他没把你们的谨慎称作胆怯。","stance":"skeptic","flag":"n5_11_1_3","dc":13,"faction":"guard"}]},{"text":"机房终于安静。格雷问还能不能回去吃那顿饭。","options":[{"label":"能。把交班责任写给我们。","reply":"萝丝留下新规：维护者有权拒绝让居民承担无期限的风险。","stance":"care","flag":"n5_11_2_0","dc":13,"faction":"guard"},{"label":"要先告诉妻子这些年发生了什么。","reply":"格雷把断齿扳手装进包里，准备带回的不是借口，是证物。","stance":"honesty","flag":"n5_11_2_1","dc":13,"faction":"guard"},{"label":"开放备用发条方案，不让它再被锁住。","reply":"工坊学徒第一次进入这间机房，知道城市也可以用另一种方法运转。","stance":"public","flag":"n5_11_2_2","dc":13,"faction":"guard"},{"label":"把残页与维护者名单送往图书馆。","reply":"你们得到的不只是契约，还有一串曾被困在临时命令里的人名。","stance":"curiosity","flag":"n5_11_2_3","dc":13,"faction":"guard"}]}]'::jsonb),
(12,'赛洛','档案 · 让真相包含盟友的错误，并让被删的人重新拥有自己的票。','[{"text":"希娜从水里取出一张票，指纹和她自己的几乎一样。","options":[{"label":"她投给谁并不重要，先把她记回来。","reply":"希娜把票装进干袋，第一次没有尝试改掉母亲选错的人。","stance":"care","flag":"n5_12_0_0","dc":14,"faction":"guard"},{"label":"埃弗签过这一行，他必须回来解释。","reply":"赛洛点头：“我不需要完美的证人，我需要不再省略的档案。”","stance":"honesty","flag":"n5_12_0_1","dc":14,"faction":"guard"},{"label":"名册的页码还连续吗？","reply":"烧过的页角遮着选区编号，删名者没法把纸的年轮一同删掉。","stance":"curiosity","flag":"n5_12_0_2","dc":14,"faction":"guard"},{"label":"[调查] 从指印与纸纹复原被删选区。","reply":"希娜协助编号，原本被判无效的选票重新有了可核验的位置。","stance":"curiosity","skill":"调查","dc":14,"failure":"湿纸破裂，你们只保住部分指印。希娜拒绝拼上猜出来的名字，要求保留缺口。","flag":"n5_12_0_3","faction":"guard"},{"label":"盟友现在倒了，谁还能保护图书馆？","reply":"“如果保护的条件是替他改记录，那这间馆早已经倒了。”","stance":"skeptic","flag":"n5_12_0_4","dc":14,"faction":"guard"},{"label":"先修水闸，再争论谁投错票。","reply":"赛洛递来扳手：“很好，总算有人愿意把脚下的问题也算政治。”","stance":"humor","flag":"n5_12_0_5","dc":14,"faction":"guard"}]},{"text":"改革派请求把批注封到听证结束，承诺资助修复整座图书馆。","options":[{"label":"拒绝封存，公开批注与完整前后文。","reply":"你们失去一笔资助，得到不会再被单独剪出的记录。","stance":"public","flag":"n5_12_1_0","dc":14,"faction":"guard"},{"label":"保留原件，先复制给地下选民核对。","reply":"希娜用母亲的旧书包送出副本，让最受影响的人先读到它。","stance":"solidarity","flag":"n5_12_1_1","dc":14,"faction":"guard"},{"label":"[说服] 让改革派接受公开核验的条件。","reply":"他们同意资助，但取消了指定解说人的条款。赛洛逐字核对，没有只相信口头承诺。","stance":"honesty","skill":"说服","dc":14,"failure":"资助被撤回。赛洛开始募捐，希娜说修复会慢，却至少不再收有条件的水桶。","flag":"n5_12_1_2","faction":"guard"},{"label":"暂缓公开，换来馆员与原件撤离。","reply":"你们保住人和纸，也必须在听证席解释为何延后。这个决定不会自动变成洗白。","stance":"bargain","flag":"n5_12_1_3","dc":14,"faction":"guard"}]},{"text":"希娜问母亲的票会不会因为选错了人而再次作废。","options":[{"label":"不会。权利不以让我们满意为条件。","reply":"她将票放到最前面，提醒未来的档案员不要替人重新选择。","stance":"care","flag":"n5_12_2_0","dc":14,"faction":"guard"},{"label":"记录选项，也记录那个选项造成的伤害。","reply":"赛洛在索引上增添异议栏，不再用整齐掩盖冲突。","stance":"honesty","flag":"n5_12_2_1","dc":14,"faction":"guard"},{"label":"请地下居民共同管理副本。","reply":"图书馆的钥匙被复制，第一次交到没有户籍的人手里。","stance":"public","flag":"n5_12_2_2","dc":14,"faction":"guard"},{"label":"把批注带给白鸦信使，让埃弗亲自回应。","reply":"赛洛写信只问一句：你还认得自己写下的这行字吗？","stance":"curiosity","flag":"n5_12_2_3","dc":14,"faction":"guard"}]}]'::jsonb),
(13,'驯养人菲恩','救援 · 阻止求救信变成别人必须付出的赎金。','[{"text":"菲恩把两个脚环握得发热，白鸦一直啄他的空掌心。","options":[{"label":"女儿为什么不肯求救？","reply":"“她知道我会答应所有条件。她想替别人省一次苦，我却仍想叫她回家。”","stance":"care","flag":"n5_13_0_0","dc":14,"faction":"guard"},{"label":"你替他们偷看过多少封信？","reply":"他报出收信人而不是数量，请你们记下：“我至少不能再让人替我统计。”","stance":"honesty","flag":"n5_13_0_1","dc":14,"faction":"guard"},{"label":"白鸦是真的忘记，还是被改过脚环？","reply":"剪口和新封蜡证明有人截信。契约的魔法之外，仍有人在有意帮凶。","stance":"curiosity","flag":"n5_13_0_2","dc":14,"faction":"guard"},{"label":"[求生] 从河岸找出最近一次截信的位置。","reply":"湿脚印停在军用船坞，安鲁认出了接头人的撑杆。","stance":"curiosity","skill":"求生","dc":14,"failure":"潮水带走脚印，你们只留下脚环编号，不能确定绑走家属的船。","flag":"n5_13_0_3","faction":"guard"},{"label":"先让菲恩离开，别人不能永远拿家人胁迫他。","reply":"“走不是坏事。但我得留下地址，好让她回来能找到我。”","stance":"solidarity","flag":"n5_13_0_4","dc":14,"faction":"guard"},{"label":"鸟肯不肯收加急费？","reply":"菲恩取出半块旧饼：“只收这个。它比我们知道什么叫够。”","stance":"humor","flag":"n5_13_0_5","dc":14,"faction":"guard"}]},{"text":"追兵要用埃弗的确切藏身处交换女儿。安鲁将船撑到桥影下面。","options":[{"label":"派白鸦追埃弗，亲自去船坞救人。","reply":"菲恩重新教鸟认塔影，自己跟你们上船。这次秘密没有被拿去付款。","stance":"solidarity","flag":"n5_13_1_0","dc":14,"faction":"guard"},{"label":"先救家属，埃弗可以再找。","reply":"白鸦收到安全脚环，寻找议员的路线暂时断开。菲恩主动留下所有旧信件补偿证据。","stance":"care","flag":"n5_13_1_1","dc":14,"faction":"guard"},{"label":"[欺骗] 送去旧地址，诱追兵远离船坞。","reply":"对方扑向废仓，安鲁撑开船底隔舱，把女儿藏到不见光的水线上。","stance":"deception","skill":"欺骗","dc":14,"failure":"追兵识破地址，船坞加强警戒。你们仍能救人，却必须面对正面截击。","flag":"n5_13_1_2","faction":"guard"},{"label":"要求菲恩先公开截信事实，再提供保护。","reply":"他答应作证，但请求不要让女儿等一份新闻来决定能否活下去。","stance":"skeptic","flag":"n5_13_1_3","dc":14,"faction":"guard"}]},{"text":"白鸦停在空脚环旁，不肯选。菲恩说鸟记得的东西比脚环少，也比人诚实。","options":[{"label":"让它带求救信，别替收信人写答案。","reply":"信只交代女儿的位置，没有再许诺出卖任何人。","stance":"honesty","flag":"n5_13_2_0","dc":14,"faction":"guard"},{"label":"拆掉有剪口的脚环，保存截信证据。","reply":"菲恩第一次允许别人碰鸟，承认秘密也应该能被核验。","stance":"curiosity","flag":"n5_13_2_1","dc":14,"faction":"guard"},{"label":"给女儿留船上空位，不让她独自躲。","reply":"安鲁多摆了一只救生圈，没有多要一枚金币。","stance":"care","flag":"n5_13_2_2","dc":14,"faction":"guard"},{"label":"让报社先保护收信人，晚些再登地址。","reply":"旧信变成警告，而不再是追捕者的新地图。","stance":"public","flag":"n5_13_2_3","dc":14,"faction":"guard"}]}]'::jsonb),
(14,'登记官莫罗','审讯 · 拆开真实纸张、合法印记与有效同意之间的差别。','[{"text":"贝丝摆出死者的旧围巾，把迁居令压在上面。","options":[{"label":"先核对送件日期，不让记忆代替证据。","reply":"莫罗打开收件簿。旧授权与新盖印分开后，矛盾不再只是贝丝的怀念。","stance":"curiosity","flag":"n5_14_0_0","dc":14,"faction":"guard"},{"label":"你替多少份命令盖过这枚印？","reply":"“四十六份。我能找齐。我不能说每份都没看懂。”他把撤职书推远。","stance":"skeptic","flag":"n5_14_0_1","dc":14,"faction":"guard"},{"label":"贝丝，你为何今天才回来？","reply":"“我以为退休就不欠这里解释了。直到我孙女住的街被写进旧命令。”","stance":"care","flag":"n5_14_0_2","dc":14,"faction":"guard"},{"label":"[历史] 分辨旧纸真实年代与新授权时间。","reply":"你们确认纸没有造假，但生效条款被新章覆盖，揭露的是合法外衣下的新命令。","stance":"honesty","skill":"历史","dc":14,"failure":"印泥覆盖太重，你们无法独立确认，必须保存原件等待公证人复核。","flag":"n5_14_0_3","faction":"guard"},{"label":"只要证词。不要求你立刻指认上司。","reply":"莫罗先写下自己负责的日期：“那我从能证明的开始，不把别人的罪塞进空格。”","stance":"solidarity","flag":"n5_14_0_4","dc":14,"faction":"guard"},{"label":"死者的印比活人的假期还长。","reply":"贝丝第一次笑了：“他当年连冬假都不肯取消。真叫他看见，会把印摔了。”","stance":"humor","flag":"n5_14_0_5","dc":14,"faction":"guard"}]},{"text":"执政官办公室要求移交原件，称你们无权检查行政档案。","options":[{"label":"封存原件，给各方一份完整副本。","reply":"莫罗留下启封记录，不再以保密代替保管。","stance":"public","flag":"n5_14_1_0","dc":14,"faction":"guard"},{"label":"只公开错位日期，暂不公布低层文书姓名。","reply":"贝丝同意先谈命令有效性，不让首轮追责只停在盖章的人身上。","stance":"care","flag":"n5_14_1_1","dc":14,"faction":"guard"},{"label":"[说服] 让莫罗拒绝没有清单的移交。","reply":"他给上级递去收件回执。谁来拿走原件，必须留下自己的名字。","stance":"solidarity","skill":"说服","dc":14,"failure":"原件被强行拿走，莫罗保下副本与移交时刻，这一次行政命令也留下可追查的尾巴。","flag":"n5_14_1_2","faction":"guard"},{"label":"带走印章，阻止继续签发。","reply":"莫罗提醒其他柜里还有印。你们截断了今晚的命令，却没解决明天的授权来源。","stance":"ruthless","flag":"n5_14_1_3","dc":14,"faction":"guard"}]},{"text":"贝丝把围巾收回去，问死人能不能终于退休。","options":[{"label":"注销旧授权，留下它曾造成的记录。","reply":"莫罗划掉有效栏，不划掉签发栏。忘记权力与忘记责任，被第一次分成两件事。","stance":"honesty","flag":"n5_14_2_0","dc":14,"faction":"guard"},{"label":"请莫罗主动写出自己的四十六份清单。","reply":"他把第一份写给你们，后四十五份留给受影响的居民。","stance":"skeptic","flag":"n5_14_2_1","dc":14,"faction":"guard"},{"label":"让被迁居民参加核验，不只通知结果。","reply":"登记处搬出第二张桌子，贝丝替不会写字的人按手印。","stance":"public","flag":"n5_14_2_2","dc":14,"faction":"guard"},{"label":"追踪原件去了谁的私人办公室。","reply":"柜门上的借阅条将线索引向停钟命令，而不只指向一个盖印职员。","stance":"curiosity","flag":"n5_14_2_3","dc":14,"faction":"guard"}]}]'::jsonb),
(15,'摆渡人萨雅','交流 · 通过自己的付出赢得地下信任，而非替居民决定如何被记住。','[{"text":"萨雅把空面具递来，等你们先决定怎样介绍自己。","options":[{"label":"说说自己害怕过、却没有逃开的事。","reply":"她留出一块空白让你们自行写下，不替你们编造身世。“这里不要求故事好听，只要求是你愿意承认的。”","stance":"honesty","flag":"n5_15_0_0","dc":14,"faction":"underground"},{"label":"我们还没准备好讲自己的事。","reply":"“可以。沉默也能有边界。”她让你们帮作坊送药，允许用劳动代替回忆。","stance":"care","flag":"n5_15_0_1","dc":14,"faction":"underground"},{"label":"你自己的故事谁来保管？","reply":"萨雅盯着面具很久：“我只记得自己曾住在能看见树的窗边。”孩子拿来绿色颜料。","stance":"solidarity","flag":"n5_15_0_2","dc":14,"faction":"underground"},{"label":"[表演] 用一段真诚的即兴故事换过河。","reply":"孩子指出你们夸张的地方，萨雅仍接过面具：“有人记住，也有人敢纠正，它才活着。”","stance":"humor","skill":"表演","dc":14,"failure":"孩子没有相信结尾，萨雅请你们改用送药换船位，不把不擅长讲述的人赶回岸上。","flag":"n5_15_0_3","faction":"underground"},{"label":"把面具上的名字公开，证明你们存在。","reply":"“那也会证明他们该来抓谁。”萨雅要求你们先征得每个家长同意。","stance":"public","flag":"n5_15_0_4","dc":14,"faction":"underground"},{"label":"给金币，别逼我拿私事过关。","reply":"她收下钱买药，但没收为船费：“你买不到别人信任，能帮他们少挨一天病。”","stance":"bargain","flag":"n5_15_0_5","dc":14,"faction":"underground"}]},{"text":"作坊来了寻找逃户的登记员，孩子们把面具倒扣在桌上。","options":[{"label":"承认自己带药来，替作坊承担盘问。","reply":"萨雅给你们船钥匙，不再让退路只能藏在她一个人手里。","stance":"solidarity","flag":"n5_15_1_0","dc":14,"faction":"underground"},{"label":"让居民自己决定谁愿意出面。","reply":"三名老住户站起来，其他人的沉默没有被写成不合作。","stance":"honesty","flag":"n5_15_1_1","dc":14,"faction":"underground"},{"label":"[欺骗] 把登记员引向废弃渡口。","reply":"面具藏入新搬来的药箱，今夜的追查扑向旧船号。","stance":"deception","skill":"欺骗","dc":14,"failure":"登记员察觉旧船无水痕，萨雅带孩子提前转移，你们失去原渡口的掩护。","flag":"n5_15_1_2","faction":"underground"},{"label":"将面具运走，不再让记忆集中在一面墙。","reply":"每户分领其他人的故事，城市再删一间作坊也抹不干净这条街。","stance":"public","flag":"n5_15_1_3","dc":14,"faction":"underground"}]},{"text":"孩子在萨雅的面具上画了一扇有树的窗。","options":[{"label":"让她自己添上记得的颜色。","reply":"她画了一点很淡的黄，说那可能是灯，也可能是日出。没有人替她定答案。","stance":"care","flag":"n5_15_2_0","dc":14,"faction":"underground"},{"label":"把船位先留给孩子和病人。","reply":"萨雅说你们可以走检修路，但她会记住谁先让了位置。","stance":"solidarity","flag":"n5_15_2_1","dc":14,"faction":"underground"},{"label":"记录匿名口述，不要求他们恢复旧姓。","reply":"法官将收到故事与同意，没人被迫靠暴露家族换取帮助。","stance":"honesty","flag":"n5_15_2_2","dc":14,"faction":"underground"},{"label":"带着面具公开请求医疗援助。","reply":"求助信不写住址，写他们需要的药量与撤离条件。","stance":"public","flag":"n5_15_2_3","dc":14,"faction":"underground"}]}]'::jsonb),
(16,'医师奥里','医疗 · 将中毒的士兵作为病人救助，而不是为剧情牺牲的疯敌人。','[{"text":"奥里按住伤兵的手腕：“他说想死的时候，先问那是不是他自己的声音。”","options":[{"label":"先稳定他，不逼他马上作证。","reply":"奥里递来绑带，注明固定时间。病人的安全不再由一纸证词决定。","stance":"care","flag":"n5_16_0_0","dc":14,"faction":"underground"},{"label":"谁签发了饮水命令？","reply":"尤萨取出抄件，命令要求先试饮再上岗；签字者从未到过盐井。","stance":"curiosity","flag":"n5_16_0_1","dc":14,"faction":"underground"},{"label":"你有证据证明不是疯病？","reply":"“绿色盐渍、同一发病时刻、停钟后的清醒。证据在他们身上，不在我是否同情。”","stance":"curiosity","flag":"n5_16_0_2","dc":14,"faction":"underground"},{"label":"[医药] 根据伤口渗盐区分病情轻重。","reply":"你们为伤兵分出能安全转移的一组，奥里得以把稀缺药留给真正急危者。","stance":"solidarity","skill":"医药","dc":14,"failure":"病况被钟声干扰，奥里接手诊断，要求你们去抬担架，避免错误处置。","flag":"n5_16_0_3","faction":"underground"},{"label":"活着的伤兵太危险，先隔离整站。","reply":"“隔离可以。断粮、弃药、封死出路不可以。”奥里要求写清期限。","stance":"skeptic","flag":"n5_16_0_4","dc":14,"faction":"underground"},{"label":"头盔先替他保管，信不会跑。","reply":"伤兵将头盔松开半寸，露出寄给母亲却从没写完的一页。","stance":"care","flag":"n5_16_0_5","dc":14,"faction":"underground"}]},{"text":"上级送来烧柜令，承诺执行后就给盐井补药。","options":[{"label":"先取原令与样本，不交病人的姓名。","reply":"尤萨盖好柜门，把追责指向饮水命令的签发者。","stance":"curiosity","flag":"n5_16_1_0","dc":14,"faction":"underground"},{"label":"带伤兵离开，柜子能保多少保多少。","reply":"奥里背起最轻的担架，留下自己签过的病历备份。","stance":"care","flag":"n5_16_1_1","dc":14,"faction":"underground"},{"label":"[说服] 要求补药不与毁证交换。","reply":"士兵送药人留下拒绝烧柜的签收条，军医第一次获得同行的支持。","stance":"honesty","skill":"说服","dc":14,"failure":"药车被调走。奥里让你们先护送重症离开，而不让病人替谈判失败付出生命。","flag":"n5_16_1_2","faction":"underground"},{"label":"将烧柜令一并送去公开核验。","reply":"想清除证据的命令本身成为新证据，上级无法只指控军医越权。","stance":"public","flag":"n5_16_1_3","dc":14,"faction":"underground"}]},{"text":"伤兵清醒后发现刀不在手里，问你们有没有替他答应死亡。","options":[{"label":"没有。那件事不能替你决定。","reply":"他请求写完家书，奥里允许在病历后面夹一页生活。","stance":"care","flag":"n5_16_2_0","dc":14,"faction":"underground"},{"label":"先记下清醒与发病的时刻。","reply":"尤萨有了可核验的症状变化，不再只剩对一个医生的信任。","stance":"curiosity","flag":"n5_16_2_1","dc":14,"faction":"underground"},{"label":"邀请愿意的人作证，不用药作交换。","reply":"两名伤兵报名，其他人仍获得相同治疗。","stance":"solidarity","flag":"n5_16_2_2","dc":14,"faction":"underground"},{"label":"让盐井家属参与病人转移。","reply":"头盔上的名字找到收信人，哨站终于不再是一组数字。","stance":"public","flag":"n5_16_2_3","dc":14,"faction":"underground"}]}]'::jsonb),
(17,'矿工乌伦','抉择 · 在复仇、取证与终止伤害之间作出不能全拿的选择。','[{"text":"兽对鲁肯的口哨低下头，又在钟声里痛得撞向井壁。","options":[{"label":"先停掉毒液，不拿它的痛当弱点。","reply":"鲁肯把闸图交来，乌伦却要求你们别因此忘了死去的矿工。","stance":"care","flag":"n5_17_0_0","dc":14,"faction":"underground"},{"label":"乌伦，你要复仇还是要弟弟的死不再发生？","reply":"他握紧斧：“两件事我都想要。别让我说得高尚，才能得到帮助。”","stance":"honesty","flag":"n5_17_0_1","dc":14,"faction":"underground"},{"label":"它为什么守着废井？","reply":"井后藏着幼兽残骸。守卫的行为第一次有了不以杀戮为目的的解释。","stance":"curiosity","flag":"n5_17_0_2","dc":14,"faction":"underground"},{"label":"[自然] 找出钟响与废液造成的异常。","reply":"你们发现兽并非随钟强化，而是因灌入甲隙的毒痛暴躁，可借停闸争取通行。","stance":"curiosity","skill":"自然","dc":14,"failure":"兽撞碎观察平台，鲁肯拉你们上石梯。你们必须通过战斗或检修路继续取证。","flag":"n5_17_0_3","faction":"underground"},{"label":"我支持杀它，但不烧掉它的饲养记录。","reply":"乌伦同意先取记录，复仇没有再被当作所有人的唯一答案。","stance":"ruthless","flag":"n5_17_0_4","dc":14,"faction":"underground"},{"label":"鲁肯，把你的口哨教给我们。","reply":"“不要学我的调子。它认得我，不欠别人听话。”他亲自走向高台。","stance":"solidarity","flag":"n5_17_0_5","dc":14,"faction":"underground"},{"label":"[战士] 用闸门的支点代替正面对撞。","reply":"你指出可供多人操作的杠杆。乌伦安排撤离者分段用力，封闸不再只是让一个战士替所有人硬撑。","failure":"闸门咬住杠杆。你撤开人手避免骨折，必须改用检修路线。","class":"战士","skill":"运动","stance":"solidarity","dc":14,"flag":"n5_class_17_0","faction":"underground"},{"label":"[游荡者] 从饲养铃的位置找出检修暗道。","reply":"铃绳穿过一扇很窄的侧门。饲养者曾从这里给兽换水，乌伦确认它通往不经过兽巢的检修口。","failure":"侧门背后垮塌，铃绳不再指向完整通道。你留下标记，提醒后来的人避开。","class":"游荡者","skill":"调查","stance":"curiosity","dc":14,"flag":"n5_class_17_1","faction":"underground"},{"label":"[法师] 分辨钟声刺激与废液变异的先后。","reply":"兽在钟响时躁动，钟停时仍痛苦。魔法刺激加剧伤害，却不是污染的全部原因；只停钟不能让井水恢复。","failure":"废液干扰了感应。你保留两个可能来源，不将实验失败归作野兽有意攻击。","class":"法师","skill":"奥秘","stance":"curiosity","dc":14,"flag":"n5_class_17_2","faction":"underground"},{"label":"[牧师] 观察它是否仍认得饲养者的动作。","reply":"乌伦缓慢放下空桶，兽后退半步。它仍会等待换水；你让人保持距离，避免把这一反应误作彻底驯服。","failure":"兽没有响应旧动作。你让乌伦撤离，不把一次没认出当成他背叛了饲养对象。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":14,"flag":"n5_class_17_3","faction":"underground"},{"label":"[游侠] 沿水位变化找出污染灌入口。","reply":"高处藻痕中断于一条新管，乌伦认出维护处后来增装的接口。污染并非井下居民自行挖出的水道。","failure":"水位刚被排过，旧痕不足以确定灌入口。你列出两处待封点，不宣称已找齐。","class":"游侠","skill":"求生","stance":"curiosity","dc":14,"flag":"n5_class_17_4","faction":"underground"},{"label":"[吟游诗人] 模仿旧饲养铃，让矿工争取撤离间隔。","reply":"低缓节拍让兽暂时望向空桶。你示意矿工离开，没把片刻停顿称作它同意继续为城市守井。","failure":"回声变成刺耳的双响，兽更加不安。你立即停声，撤离队伍改从侧壁走。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":14,"flag":"n5_class_17_5","faction":"underground"},{"label":"[圣武士] 说服矿工分开记录“保护大家”与“处置野兽”。","reply":"乌伦同意先清点活人，再决定封井与捕杀。你们无需用击杀数量证明已经救出矿工。","failure":"矿工仍要求立即杀兽。乌伦保留异议，撤离名单照常清点。","class":"圣武士","skill":"说服","stance":"honesty","dc":14,"flag":"n5_class_17_6","faction":"underground"}]},{"text":"闸门锁柄开始松动，乌伦的斧已经举起。","options":[{"label":"准备战斗，指定一人保护毒液闸。","reply":"你们把杀兽与控制废液分开，避免赢了战斗却让下游居民中毒。","stance":"solidarity","flag":"n5_17_1_0","dc":14,"faction":"underground"},{"label":"沿检修路绕行，让鲁肯引开兽。","reply":"乌伦不认同，却跟着你们去寻找真正倒毒的人。他的仇没有被假装化解。","stance":"care","flag":"n5_17_1_1","dc":14,"faction":"underground"},{"label":"[运动] 固定绞盘，先封住毒液侧井。","reply":"兽在钟声里不再受灌注折磨，留给你们一条安静的取证窗口。","stance":"curiosity","skill":"运动","dc":14,"failure":"锁柄断裂，鲁肯用旧支撑顶住。你们失去固定窗口，必须尽快完成战斗或绕行。","flag":"n5_17_1_2","faction":"underground"},{"label":"击碎吊灯，优先阻断兽的追击。","reply":"道路被照亮，也暴露出更多被毒杀的幼兽。乌伦没有欢呼。","stance":"ruthless","flag":"n5_17_1_3","dc":14,"faction":"underground"}]},{"text":"井下不再传来撞壁声，乌伦仍握着没有归鞘的斧。","options":[{"label":"陪他找到弟弟留下的工牌。","reply":"工牌不是战利品。鲁肯替它清掉毒盐，将姓名交回家属。","stance":"care","flag":"n5_17_2_0","dc":14,"faction":"underground"},{"label":"让饲养人与矿工分别写下经过。","reply":"兽的故事不再只有怪物与勇士两个角色。","stance":"honesty","flag":"n5_17_2_1","dc":14,"faction":"underground"},{"label":"把废液出库号一起送往法官。","reply":"兽的甲壳与高堂的银桶终于接成一条责任链。","stance":"curiosity","flag":"n5_17_2_2","dc":14,"faction":"underground"},{"label":"请乌伦守住关闸，不再守着兽头。","reply":"他把斧挂回背上：“这件事我能做，但别说我已经原谅。”","stance":"solidarity","flag":"n5_17_2_3","dc":14,"faction":"underground"}]}]'::jsonb),
(18,'无名法官','护送 · 保护真相的持有人，同时允许他们指认保护者的罪。','[{"text":"法官撕下遮住签名的纸：“先看这一页，再决定我还能不能发问。”","options":[{"label":"你保护证人，是为了赎罪还是为了控制他们？","reply":"“两者都有。后来我把钥匙交给丹缇，至少让害怕我的人也能自己出去。”","stance":"skeptic","flag":"n5_18_0_0","dc":15,"faction":"underground"},{"label":"先保护起诉你的人。","reply":"老妇抬起头，第一次允许你们靠近她带来的旧门钥匙。","stance":"care","flag":"n5_18_0_1","dc":15,"faction":"underground"},{"label":"临时驱逐的条件由谁删掉？","reply":"法官指出当年维护处与现在办公室使用同一授权条款，骗局跨过了几任名字。","stance":"curiosity","flag":"n5_18_0_2","dc":15,"faction":"underground"},{"label":"[洞悉] 请他区分记得的事实与替自己的辩解。","reply":"他划掉口供中的“不得已”，留下日期、命令与本人签名。","stance":"honesty","skill":"洞悉","dc":15,"failure":"他把解释说得很圆满。丹缇拿出另一份笔录，提醒必须让证人独立核对。","flag":"n5_18_0_3","faction":"underground"},{"label":"案卷可以拿，赦免不能答应。","reply":"“我知道。”他退到证人旁边，不再坐他们面前。","stance":"honesty","flag":"n5_18_0_4","dc":15,"faction":"underground"},{"label":"这屋子总算有一个承认自己记性不好的人。","reply":"老妇冷笑：“他记性好得很。今天只是肯把记得的事写出来。”","stance":"humor","flag":"n5_18_0_5","dc":15,"faction":"underground"}]},{"text":"撤离图的一条出口已被封。女儿和老妇要走不同的方向。","options":[{"label":"先护送愿意起诉的人，家属走第二批。","reply":"法官没有阻拦，丹缇改写次序，老妇终于知道保护并非拿她的沉默交换。","stance":"solidarity","flag":"n5_18_1_0","dc":15,"faction":"underground"},{"label":"分散护卫，两批都不共用名单。","reply":"单一路线泄露不再毁掉所有证人，护卫的人手也因此更薄。","stance":"care","flag":"n5_18_1_1","dc":15,"faction":"underground"},{"label":"[说服] 请求法官留下作诱饵，掩护两批离开。","reply":"他穿回旧法袍，第一次以自己的名字承担风险，而非调用别人的安全。","stance":"public","skill":"说服","dc":15,"failure":"他无法站稳，丹缇接过诱饵工作，你们必须另留护卫防止追兵发现。","flag":"n5_18_1_2","faction":"underground"},{"label":"换取地下护卫，不由你们独占撤离方案。","reply":"居民提供出口，条件是听证后仍公开所有被告，包括法官。","stance":"bargain","flag":"n5_18_1_3","dc":15,"faction":"underground"}]},{"text":"法官问如果证人不愿宽恕，他还有没有资格活到判决日。","options":[{"label":"有。宽恕与活着受审是两回事。","reply":"老妇要求把这句话也写进公开记录，免得日后只用在权贵身上。","stance":"honesty","flag":"n5_18_2_0","dc":15,"faction":"underground"},{"label":"这个问题该由她们回答，你先听着。","reply":"法官第一次没有接话，老妇终于讲完自己的房子怎么被拆掉。","stance":"care","flag":"n5_18_2_1","dc":15,"faction":"underground"},{"label":"把他的签名和证人的地址分开保管。","reply":"案卷可以公开，退路不能跟着公开。","stance":"curiosity","flag":"n5_18_2_2","dc":15,"faction":"underground"},{"label":"承诺护送，但不承诺法官的判决。","reply":"丹缇交出完整撤离图，接过的是明确的边界而非模糊的忠诚。","stance":"solidarity","flag":"n5_18_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(19,'议员埃弗','审讯 · 找到一个逃避责任的活人，而非给失踪英雄写洗白结尾。','[{"text":"埃弗将写着“父亲”的纸推向你们：“她还会认我吗？”","options":[{"label":"先说莉安的证词，不替你处理家事。","reply":"他把道歉稿收回去，报出焚证地点和授意的人。","stance":"skeptic","flag":"n5_19_0_0","dc":15,"faction":"underground"},{"label":"你女儿可以不原谅，你仍要回去解释。","reply":"“我知道。”他说得太快。伊莱娅要求他重复一遍，不带如果。","stance":"honesty","flag":"n5_19_0_1","dc":15,"faction":"underground"},{"label":"你为何把我们的名字写进邀请？","reply":"“莉安选的是能看见空白的人。我加了酬劳，想让你们只查办公室，不查我。”","stance":"curiosity","flag":"n5_19_0_2","dc":15,"faction":"underground"},{"label":"[说服] 让他用真名签下完整供词。","reply":"他签完手发抖，先前被抹去的批注重新出现。姓名回来，责任也回来。","stance":"public","skill":"说服","dc":15,"failure":"他停在姓氏前面，只肯提供事实不肯签字。你们仍可用独立证物追责，无法将此作完整自认。","flag":"n5_19_0_3","faction":"underground"},{"label":"你若作证，我们保护你到受审。","reply":"“到受审。”他重复了这三个字，终于不把保护听成赦免。","stance":"solidarity","flag":"n5_19_0_4","dc":15,"faction":"underground"},{"label":"你写了那么多演讲，怎么一句道歉都写不完？","reply":"伊莱娅接话：“因为道歉不能替听的人鼓掌。”他没有再拿起笔。","stance":"humor","flag":"n5_19_0_5","dc":15,"faction":"underground"}]},{"text":"埃弗提供停钟权限，条件是别让女儿在公开席听见焚证。","options":[{"label":"拒绝隐瞒，但允许孩子不出席。","reply":"伊莱娅负责解释公开与强迫旁听的区别，他第一次没有拿孩子替自己遮挡。","stance":"honesty","flag":"n5_19_1_0","dc":15,"faction":"underground"},{"label":"先收权限，延后供词到孩子安全撤离。","reply":"你们留下明确公开日期，承诺不会变成无限期秘密。","stance":"care","flag":"n5_19_1_1","dc":15,"faction":"underground"},{"label":"[威吓] 现在不签，就由受害者指认你。","reply":"他面对门外的老妇签完了姓氏，知道证词并不只属于他自己。","stance":"threat","skill":"威吓","dc":15,"failure":"他退回无名身份，拒绝签署。伊莱娅留下原稿，与证人一起独立追查。","flag":"n5_19_1_2","faction":"underground"},{"label":"不交易权限，把所有事实交给听证。","reply":"你们会更难进入办公室，却不让揭露的时机被被告挑选。","stance":"public","flag":"n5_19_1_3","dc":15,"faction":"underground"}]},{"text":"他女儿留下的贺卡被放在桌上，那个错字还在。","options":[{"label":"把贺卡交给他，不代替孩子说原谅。","reply":"埃弗收好纸，第一次没有要求听到一个好结尾。","stance":"care","flag":"n5_19_2_0","dc":15,"faction":"underground"},{"label":"请他亲自与烧掉证词的受害者对话。","reply":"伊莱娅退开一步，让他站到没有讲台的位置。","stance":"honesty","flag":"n5_19_2_1","dc":15,"faction":"underground"},{"label":"保护愿意作证的他，继续追究焚证。","reply":"城里将出现一个仍可能被定罪、也仍值得保护的证人。","stance":"solidarity","flag":"n5_19_2_2","dc":15,"faction":"underground"},{"label":"让报社刊出真实供词，而非他的演讲。","reply":"莉缇收到一份没有胜利修辞的原稿，保留所有自我矛盾。","stance":"public","flag":"n5_19_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(20,'镜厅侍者菲娅','幻象 · 拒绝为了避免预言，而亲手把预言变成事实。','[{"text":"菲娅指着镜中的自己：“如果我已经带走证人，为什么她还在这里？”","options":[{"label":"别看镜子，先确认眼前的人。","reply":"老妇接过水杯，菲娅按住真实门栓。大家第一次停止等待画面里的动作。","stance":"care","flag":"n5_20_0_0","dc":15,"faction":"underground"},{"label":"镜里有哪一件事还没发生？","reply":"镜匠指出翻倒的杯子，证明镜像制造的是选择诱导，而不是不可改写的未来。","stance":"curiosity","flag":"n5_20_0_1","dc":15,"faction":"underground"},{"label":"护卫的倒影背叛，不代表护卫已经背叛。","reply":"士兵松开剑柄，愿意一起核验门锁，而非先解释一个他没做过的罪。","stance":"honesty","flag":"n5_20_0_2","dc":15,"faction":"underground"},{"label":"[奥秘] 找出能投射假未来的镜轴。","reply":"你们调转延迟的灯，刺客的真实侧廊在镜上露出短暂重影。","stance":"curiosity","skill":"奥秘","dc":15,"failure":"镜轴回弹，更多假未来涌出。纳因请你们按鞋泥和门痕找人，不再信镜面的答案。","flag":"n5_20_0_3","faction":"underground"},{"label":"砸掉全部镜子，证人先撤。","reply":"菲娅担心失去刺客踪迹，仍先护住老妇的眼睛。","stance":"ruthless","flag":"n5_20_0_4","dc":15,"faction":"underground"},{"label":"若它真能看明天，能不能先报明天的菜价？","reply":"老妇笑了，镜中的她却没有笑。最简单的不一致突然比所有预言都可靠。","stance":"humor","flag":"n5_20_0_5","dc":15,"faction":"underground"},{"label":"[战士] 盯住真实地板，而不是镜里的出剑动作。","reply":"地板上只有一道新划痕，倒影却演出三次攻击。你让护卫收剑，先查真正经过走廊的人。","failure":"镜光盖住划痕。你只能让护卫拉开距离，无法从现有痕迹认定袭击者。","class":"战士","skill":"运动","stance":"solidarity","dc":15,"flag":"n5_class_20_0","faction":"underground"},{"label":"[游荡者] 找出镜轴转动时被藏住的脚印。","reply":"半枚鞋印沿镜框背后移动。刺客一直在控制看见的角度，不是从预言里跨进大厅。","failure":"脚印被洒过的水冲开。你确认有人整理过现场，无法锁定那人的鞋底。","class":"游荡者","skill":"调查","stance":"curiosity","dc":15,"flag":"n5_class_20_1","faction":"underground"},{"label":"[法师] 验证倒影是否拥有独立的时间来源。","reply":"每个所谓未来都随镜轴调整重演同一个停顿。装置展示的是拼接画面，不能替听证人预先定罪。","failure":"镜厅的反馈把自己的动作也复制进去。你中止验证，不让新的片段混成证据。","class":"法师","skill":"奥秘","stance":"curiosity","dc":15,"flag":"n5_class_20_2","faction":"underground"},{"label":"[牧师] 让“未来的背叛者”说出此刻真正害怕什么。","reply":"证人怕的是你们会先相信镜子，再问他为什么。你让他坐在没有反光的墙边，先核对现实中的去向。","failure":"证人惊惶到说不完整。你留下空白，不用镜里的声音替他补一句认罪。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":15,"flag":"n5_class_20_3","faction":"underground"},{"label":"[游侠] 核对镜中风向与走廊真实气流。","reply":"镜里的衣角向相反方向摆动。画面来自另一个开口，你让众人注意镜框后的通风暗格。","failure":"厅内对流让衣角方向不稳定。你仍检查暗格，但不把风向当作决定性证据。","class":"游侠","skill":"求生","stance":"curiosity","dc":15,"flag":"n5_class_20_4","faction":"underground"},{"label":"[吟游诗人] 故意表演一段没有发生过的背叛，观察镜子跟不跟。","reply":"镜子抢先复制了你刚编的台词。护卫看见所谓预言也会临时改稿，终于不再把它当成军令。","failure":"镜子没有跟随。护卫仍保持怀疑，你必须继续用真实记录核验。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":15,"flag":"n5_class_20_5","faction":"underground"},{"label":"[圣武士] 要求任何人不得因未发生的罪被处决。","reply":"护卫把剑尖放低。菲娅允许你们先带证人离开视线，镜中的判决第一次没能在走廊得到执行。","failure":"护卫坚持封锁。你记录命令来源，证人仍活着，谈判没有变成当场判罪。","class":"圣武士","skill":"说服","stance":"honesty","dc":15,"flag":"n5_class_20_6","faction":"underground"}]},{"text":"侧廊暗门只能撑十息，刺客与证人分在两端。","options":[{"label":"封锁长廊，留下人护住证人。","reply":"纳因关镜轴，刺客失去假未来的掩护。你们不能再靠所有人一起追击。","stance":"solidarity","flag":"n5_20_1_0","dc":15,"faction":"underground"},{"label":"优先送证人过暗门，放弃立即追凶。","reply":"老妇活着离开，刺客的身份需要靠军械库泥重新追查。","stance":"care","flag":"n5_20_1_1","dc":15,"faction":"underground"},{"label":"[察觉] 在十息内辨认真影与假影。","reply":"你们找到鞋泥不随镜光改变的那个人，菲娅保住了暗门出口。","stance":"curiosity","skill":"察觉","dc":15,"failure":"假影挡住视线，菲娅只能先救人。刺客退入军需仓，留下新的追查难题。","flag":"n5_20_1_2","faction":"underground"},{"label":"假装相信背叛画面，让刺客自己靠近。","reply":"护卫接受你们的假指控作为诱饵，要求战后当众澄清。","stance":"deception","flag":"n5_20_1_3","dc":15,"faction":"underground"}]},{"text":"护卫问，事先看到过“背叛”以后，你们还会让他守门吗？","options":[{"label":"会。我们判断的是你做过的事。","reply":"他收起假指控的记录，决定继续护送证人，而非逃离自己的预言。","stance":"honesty","flag":"n5_20_2_0","dc":15,"faction":"underground"},{"label":"轮值守门，不让谁只能独自承担怀疑。","reply":"菲娅安排两人互证，这道门终于依靠规则而非猜测。","stance":"solidarity","flag":"n5_20_2_1","dc":15,"faction":"underground"},{"label":"先向他道歉，再要求解释真实的军令。","reply":"歉意没有取代核验，核验也没有被当作惩罚。","stance":"care","flag":"n5_20_2_2","dc":15,"faction":"underground"},{"label":"把镜术公开，让市民知道预言也能造假。","reply":"纳因保留一片镜轴，用自己的名字说明如何制造恐惧。","stance":"public","flag":"n5_20_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(21,'钟匠杜伦','危机 · 让改变城市运转的费用不再只由被抹去的人承担。','[{"text":"杜伦拿出最后一枚绝缘环，问应该先保护总钟，还是地下水闸。","options":[{"label":"先问地下的人，不替他们决定能淹多少。","reply":"奥雅打通报时管，萨雅的声音从井里传来：“不是我们先死，再等你们讨论。”","stance":"solidarity","flag":"n5_21_0_0","dc":15,"faction":"underground"},{"label":"谁下的停钟命令？","reply":"“执政官想让你们撤案，改革派想让他辞职。井里的人没有同意当计时器。”","stance":"curiosity","flag":"n5_21_0_1","dc":15,"faction":"underground"},{"label":"安全发条为什么一直没有启用？","reply":"“地上要停水三天，修复费也不能再由被删户承担。”奥雅把账单翻到背面。","stance":"skeptic","flag":"n5_21_0_2","dc":15,"faction":"underground"},{"label":"[奥秘] 用绝缘环隔开姓名契约与铜线。","reply":"第一座钟恢复物理运转，不再收走名字。其余城区需要共同承担检修。","stance":"curiosity","skill":"奥秘","dc":15,"failure":"环过热，你们只隔开一个侧井，必须通过办公室原令关闭其余收债线路。","flag":"n5_21_0_3","faction":"underground"},{"label":"愿意支付修复，但不能替全城签字。","reply":"杜伦组织公开停水通知，明确不是英雄付钱就能免除所有人的选择。","stance":"honesty","flag":"n5_21_0_4","dc":15,"faction":"underground"},{"label":"先把这三天停水写进候选人的演讲。","reply":"奥雅将稿纸递给改革派：“别只把承担二字留给井下。”","stance":"humor","flag":"n5_21_0_5","dc":15,"faction":"underground"}]},{"text":"改革派提供办公室通行证，要求先复钟，再讨论全面解除。","options":[{"label":"潜入取原令，不签复钟交换条款。","reply":"你们失去办公室的保护，保留对整条收债线路的调查自由。","stance":"curiosity","flag":"n5_21_1_0","dc":15,"faction":"underground"},{"label":"接触改革派，但要求公开停水方案。","reply":"他们不得不面对地上居民，支持开始有真实成本。","stance":"public","flag":"n5_21_1_1","dc":15,"faction":"underground"},{"label":"[说服] 说服各城区分担安全发条改造。","reply":"总钟维护者获得可执行的预算，萨雅要求将井下监督席写进方案。","stance":"solidarity","skill":"说服","dc":15,"failure":"富城区拒绝分担。你们保住地下侧井，仍须在断桥后组织更广的协商。","flag":"n5_21_1_2","faction":"underground"},{"label":"暂时复钟，只赎回眼前最危险的居民。","reply":"你们避免即时溃闸，也留下未被赎回者的清单。暂时不能再被写成没有期限。","stance":"bargain","flag":"n5_21_1_3","dc":15,"faction":"underground"}]},{"text":"杜伦听见第一声不收姓名的钟，竟不知道该不该欢呼。","options":[{"label":"先检查井下，再宣布恢复。","reply":"报时管传来萨雅的平安回复，这声钟终于没有只代表上城区。","stance":"care","flag":"n5_21_2_0","dc":15,"faction":"underground"},{"label":"公开账单与分担者，不把改造叫奇迹。","reply":"奥雅将零件价贴在机房门外，未来的维护也能被质疑。","stance":"public","flag":"n5_21_2_1","dc":15,"faction":"underground"},{"label":"把恢复权限分给三个不同城区。","reply":"办公室失去独占报时的钥匙，停钟不再是一个人的威胁。","stance":"solidarity","flag":"n5_21_2_2","dc":15,"faction":"underground"},{"label":"给所有暂时措施写上到期日。","reply":"杜伦盖下新章：逾期必须重新征得受影响者同意。","stance":"honesty","flag":"n5_21_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(22,'桥卫雷蒙','谈判 · 兑现旧承诺，同时拒绝让旧盟友替你们决定所有敌人。','[{"text":"雷蒙让你们放下证物箱。阿蒙在桥下示意不要照做。","options":[{"label":"两边各派一人开箱。","reply":"雷蒙交钥匙，阿蒙交门图。谁也不能再只检查自己愿意看到的半辆车。","stance":"honesty","flag":"n5_22_0_0","dc":15,"faction":"underground"},{"label":"雷蒙，命令有没有写明不准居民旁听？","reply":"他念到备注时停住。那条权限来自口头补充，不在原令里。","stance":"curiosity","flag":"n5_22_0_1","dc":15,"faction":"underground"},{"label":"阿蒙，我们记得保护承诺，不答应攻击所有士兵。","reply":"他松开钩：“那也别把没扔石头的人，算进你们需要安抚的暴民。”","stance":"solidarity","flag":"n5_22_0_2","dc":15,"faction":"underground"},{"label":"[说服] 要求双方让担架与发条先过桥。","reply":"桥面让出窄道，争论没有结束，等待药的人却先得救了。","stance":"care","skill":"说服","dc":15,"failure":"双方坚持查车，担架改走旧工人路线，你们需要之前取得的居民信任。","flag":"n5_22_0_3","faction":"underground"},{"label":"借检修道离开，不卷入桥面争执。","reply":"阿蒙让路，却提醒你们承诺不会跟着消失：通行是帮助，不是替你们办完问题。","stance":"skeptic","flag":"n5_22_0_4","dc":15,"faction":"underground"},{"label":"车能过去，人不行。这桥是修给箱子的吗？","reply":"雷蒙看向车里的迁居纸，终于肯让搬货的新兵一并下车。","stance":"humor","flag":"n5_22_0_5","dc":15,"faction":"underground"}]},{"text":"车底发现迁居纸，雷蒙的封桥令瞬间成了包庇的证据。","options":[{"label":"公布原件，但允许雷蒙解释签收链。","reply":"阿蒙愿听，条件是不能再用不知情结束所有责任。","stance":"public","flag":"n5_22_1_0","dc":15,"faction":"underground"},{"label":"请旧盟友护送证人，不围攻新兵。","reply":"工人把人从冲突里分开，保护不再等于加入同一场殴斗。","stance":"care","flag":"n5_22_1_1","dc":15,"faction":"underground"},{"label":"[威吓] 逼军官将口头补充令签名。","reply":"军官不肯签，新兵看见了命令与责任如何被分给不同的人。","stance":"threat","skill":"威吓","dc":15,"failure":"军官拒绝核验，雷蒙保住副本，你们只能带证人从桥底先走。","flag":"n5_22_1_2","faction":"underground"},{"label":"扣留纸张，发条照常运往机房。","reply":"救援与控罪分开处理，车队不能再拿一件好事遮住另一件坏事。","stance":"honesty","flag":"n5_22_1_3","dc":15,"faction":"underground"}]},{"text":"雷蒙问如果放行，谁保证明天他不会被当作叛徒。","options":[{"label":"没有人能保证，但你的行动会被公开记录。","reply":"他接受署名，不再让未来的无罪成为今天帮忙的条件。","stance":"honesty","flag":"n5_22_2_0","dc":15,"faction":"underground"},{"label":"让工人与新兵共同护送车队。","reply":"阿蒙先为新兵指明桥底台阶，合作从搬一只箱子开始。","stance":"solidarity","flag":"n5_22_2_1","dc":15,"faction":"underground"},{"label":"给伤者留路，不要求双方立刻握手。","reply":"担架终于过桥，憎恨没有被一道过场对话虚假抹平。","stance":"care","flag":"n5_22_2_2","dc":15,"faction":"underground"},{"label":"把封桥令贴在桥头，不由队长保管。","reply":"谁都能读，谁也不能再声称那只是你们的传言。","stance":"public","flag":"n5_22_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(23,'馆员梅瑞','救援 · 在火灾中立即作出救援决定，不把活人锁在调查进度后面。','[{"text":"梅瑞的声音从烟里传来：“这里有人！别先问他姓什么！”","options":[{"label":"先救人，纸湿了以后再修。","reply":"欧宁扭开水闸，火退了一步。几份原件湿透，但孩子还能咳出声音。","stance":"care","flag":"n5_23_0_0","dc":15,"faction":"underground"},{"label":"证据有没有分藏的副本？","reply":"赛洛报出你们曾交给居民的地址；若此前封存，他只能报出楼上唯一的柜号。","stance":"curiosity","flag":"n5_23_0_1","dc":15,"faction":"underground"},{"label":"分人守原件，余下的人进宿舍。","reply":"梅瑞给护档者一条绳，确保撤退不需要靠勇气猜楼梯还在不在。","stance":"solidarity","flag":"n5_23_0_2","dc":15,"faction":"underground"},{"label":"[运动] 抬起塌下来的门梁。","reply":"欧宁将孩子拖出，水闸终于不用再被他一只手死撑。","stance":"care","skill":"运动","dc":15,"failure":"门梁滑回，梅瑞找到另一出口。你们仍能救人，但必须丢下门边的资料箱。","flag":"n5_23_0_3","faction":"underground"},{"label":"不让馆员进去，我们自己去。","reply":"梅瑞拒绝被当作待救道具，指明她熟悉的楼梯，愿意与你们同行。","stance":"honesty","flag":"n5_23_0_4","dc":15,"faction":"underground"},{"label":"纵火者烧宿舍，是为了诱我们离开原件。","reply":"欧宁点头：“所以别让他们决定人和纸只能保一个。先关火油阀。”","stance":"skeptic","flag":"n5_23_0_5","dc":15,"faction":"underground"}]},{"text":"楼上抛下火油罐，原件与出口之间都是碎玻璃。","options":[{"label":"组织守卫控制火油，不追逃跑的人。","reply":"纵火者留下活口，可能指认雇主，出口则保住了最后一批馆员。","stance":"solidarity","flag":"n5_23_1_0","dc":15,"faction":"underground"},{"label":"先救梅瑞和孩子，原件尽量复制。","reply":"你们无法声称完好保全，却让能解释纸页的人活下来。","stance":"care","flag":"n5_23_1_1","dc":15,"faction":"underground"},{"label":"[调查] 找出尚未燃烧的油路与总阀。","reply":"火势被切断，馆员开始从对面抢救原件，争取到同时撤离的窗口。","stance":"curiosity","skill":"调查","dc":15,"failure":"总阀受热卡死，欧宁改开水闸。原件受损，但孩子和出口没有被油吞没。","flag":"n5_23_1_2","faction":"underground"},{"label":"将原件抛入水池，宁可损坏也不让它燃烧。","reply":"梅瑞记下哪几页先入水，后续公证会知道损坏如何发生，不把修补冒充原始。","stance":"honesty","flag":"n5_23_1_3","dc":15,"faction":"underground"}]},{"text":"赛洛捡起一片烧焦目录，问你们还能不能说档案完整。","options":[{"label":"不能。把缺页和抢救经过一并公开。","reply":"他写下缺损说明，真相不靠一场胜利宣称自己从未破碎。","stance":"honesty","flag":"n5_23_2_0","dc":15,"faction":"underground"},{"label":"先清点活人，再清点纸。","reply":"梅瑞读出每个馆员名字，欧宁读到自己的时候笑了一下。","stance":"care","flag":"n5_23_2_1","dc":15,"faction":"underground"},{"label":"向居民调回此前保存的副本。","reply":"分藏终于不再是一句好听承诺，替你们补回真实内容。","stance":"public","flag":"n5_23_2_2","dc":15,"faction":"underground"},{"label":"让被救的纵火者也接受审理。","reply":"复仇没有把追查终结在放火的人身上，雇佣关系仍须查清。","stance":"skeptic","flag":"n5_23_2_3","dc":15,"faction":"underground"}]}]'::jsonb),
(24,'工人领袖露佩','表决 · 让居民决定未来，包括允许他们反对救过自己的冒险者。','[{"text":"露佩把发言牌交给一名反对你们的工人。","options":[{"label":"允许。他的反对不取消得到保护的资格。","reply":"他讲完桥上的事，没人要求他先感谢你们。露佩记下第一条底线。","stance":"honesty","flag":"n5_24_0_0","dc":16,"faction":"underground"},{"label":"先把土地归属写清，再分席位。","reply":"法伊圈出四份方案共同回避的租户资格，争执第一次触及生活而非口号。","stance":"curiosity","flag":"n5_24_0_1","dc":16,"faction":"underground"},{"label":"让地下代表先讲，他们已经等了太久。","reply":"萨雅拿出空面具，不公布孩子藏身处，也不再以神秘换取同情。","stance":"care","flag":"n5_24_0_2","dc":16,"faction":"underground"},{"label":"[说服] 要求各派公开接受监督与撤回机制。","reply":"四份文本增添罢免条款，支持者不再拥有永远代表别人的授权。","stance":"public","skill":"说服","dc":16,"failure":"两派拒绝签署，露佩将拒绝也写上白板，居民可以据此选择，而不是被骗成共识。","flag":"n5_24_0_3","faction":"underground"},{"label":"我们救过你们，至少该信一次。","reply":"法伊问那一次信任何时到期。你们的功劳没有自动变成席位。","stance":"threat","flag":"n5_24_0_4","dc":16,"faction":"underground"},{"label":"坐最后一排也好，逃课不容易被发现。","reply":"露佩笑着把记录册递来：“今天谁也不许漏作业，尤其救过人的。”","stance":"humor","flag":"n5_24_0_5","dc":16,"faction":"underground"}]},{"text":"投票要开始，有人请求删掉会让联盟分裂的争议条款。","options":[{"label":"保留条款与异议，不制造全票通过。","reply":"居民看到分歧，选择不再被漂亮的会议纪要代替。","stance":"honesty","flag":"n5_24_1_0","dc":16,"faction":"underground"},{"label":"举行公开集会，争议交给受影响者。","reply":"议事场扩到街外，地下居民有座位，也有不投票的自由。","stance":"public","flag":"n5_24_1_1","dc":16,"faction":"underground"},{"label":"[洞悉] 找出谁拿救援当永久政治授权。","reply":"你们指出资助与监督的捆绑，法伊要求单独表决，不让药物成为勒索。","stance":"curiosity","skill":"洞悉","dc":16,"failure":"动机无法证实，你们只能要求条款公开，不能随意宣布别人有罪。","flag":"n5_24_1_2","faction":"underground"},{"label":"先写医疗与撤离公约，制度明天再争。","reply":"今天没人失去药，明天也必须继续开会。拖延有期限，不算胜利。","stance":"care","flag":"n5_24_1_3","dc":16,"faction":"underground"}]},{"text":"露佩问新的制度里，你们准备占多少席位。","options":[{"label":"不占终身席，按同样规则参与。","reply":"她收回为英雄预留的椅子，给你们普通报名表。","stance":"honesty","flag":"n5_24_2_0","dc":16,"faction":"underground"},{"label":"先当护卫，让发言的人不必怕报复。","reply":"工人第一次从你们的剑旁走向讲台，而不是被剑指向讲台。","stance":"solidarity","flag":"n5_24_2_1","dc":16,"faction":"underground"},{"label":"保留观察席，公开我们一路的决定。","reply":"法伊会把保护与威胁都写进记录，你们不能只提供好看的章节。","stance":"public","flag":"n5_24_2_2","dc":16,"faction":"underground"},{"label":"拒绝替任何派系背书。","reply":"露佩接受，仍要求你们兑现此前的具体保护承诺。","stance":"skeptic","flag":"n5_24_2_3","dc":16,"faction":"underground"}]}]'::jsonb),
(25,'公证人希尔','契约 · 拒绝用一份古老真契约，把不公重新包装成正确结局。','[{"text":"墨水师娅拉用侧灯照出被刮掉的一句话：“本人不同意后代代为承受。”","options":[{"label":"把背面一起鉴定，不能只确认正面。","reply":"希尔落下两处鉴定章，契约的罪也与它的合法年代一同成立。","stance":"honesty","flag":"n5_25_0_0","dc":16,"faction":"underground"},{"label":"谁替那些手印的人解释过条款？","reply":"“没人。他们被告知只是签收救济。”娅拉不再把手印叫自愿。","stance":"skeptic","flag":"n5_25_0_1","dc":16,"faction":"underground"},{"label":"莉安留的是请求，不是必须完成的使命。","reply":"铜匣上的名字不再继续生长，契约第一次承认你们没有答应的部分。","stance":"care","flag":"n5_25_0_2","dc":16,"faction":"underground"},{"label":"[历史] 核验免责条款与后代义务的年代。","reply":"免责更早，继承义务是后来压在它上面的新墨。公证不再只证明纸是真的。","stance":"curiosity","skill":"历史","dc":16,"failure":"年代界线仍有疑问，娅拉拒绝盖完全恢复的章，要求公开不确定性。","flag":"n5_25_0_3","faction":"underground"},{"label":"如果撕掉契约，城钟会怎样？","reply":"“旧债不会自动消失。得另立运转与赔偿的约定。”希尔把发条方案一同放上桌。","stance":"curiosity","flag":"n5_25_0_4","dc":16,"faction":"underground"},{"label":"这么大一张纸，原来连一句不同意都容不下。","reply":"娅拉把被刮掉的句子重新描出：“今晚可以先容下这一句。”","stance":"humor","flag":"n5_25_0_5","dc":16,"faction":"underground"}]},{"text":"各派都伸手要原件，声称只有自己能保管。","options":[{"label":"鉴定后封存，由居民共同持钥。","reply":"希尔要求双签启封，任何派系都不能单独改背面。","stance":"public","flag":"n5_25_1_0","dc":16,"faction":"underground"},{"label":"邀请所有派系核验，再另立新约。","reply":"争论并未停止，但每个人读到的是同一张纸，没有私人版本。","stance":"solidarity","flag":"n5_25_1_1","dc":16,"faction":"underground"},{"label":"[说服] 让各派接受不继承未经同意的义务。","reply":"地下孩子不再自动成为总钟的抵押物，新的预算必须有人真正签字承担。","stance":"care","skill":"说服","dc":16,"failure":"部分买家拒绝解除继承，拒绝者被公开列入异议，不再能藏在全体同意下面。","flag":"n5_25_1_2","faction":"underground"},{"label":"废止旧约，保留原件作为追责证据。","reply":"撕毁不是唯一废止办法。希尔将失效与销毁分开，过去不会随新制度消失。","stance":"honesty","flag":"n5_25_1_3","dc":16,"faction":"underground"}]},{"text":"娅拉问你们的姓名是否也该写在最后一行。","options":[{"label":"只签自己愿意承担的事，不替居民签。","reply":"她留下空位给下一场公开表决，英雄的笔也要守边界。","stance":"honesty","flag":"n5_25_2_0","dc":16,"faction":"underground"},{"label":"以见证人身份签，不领取土地权。","reply":"契约多出的是责任，不是奖励英雄的新领地。","stance":"solidarity","flag":"n5_25_2_1","dc":16,"faction":"underground"},{"label":"等受影响的人读完再签。","reply":"希尔把灯借给不会读字的人，一句句念背面的原文。","stance":"care","flag":"n5_25_2_2","dc":16,"faction":"underground"},{"label":"不签，但交出一路取得的原件。","reply":"你们可以退出契约，不可以带走别人的追责依据。","stance":"skeptic","flag":"n5_25_2_3","dc":16,"faction":"underground"}]}]'::jsonb),
(26,'凯尔·索恩','停战 · 争取真正的停战，同时不替任何一方承诺免罪。','[{"text":"凯尔取下头盔：“我不替上级清白，你们也别替居民决定谁该被杀。”","options":[{"label":"同意。放下武器与接受审理一起做。","reply":"柏戈拿出夹层原件，第一名新兵跟着放低枪口。","stance":"honesty","flag":"n5_26_0_0","dc":16,"faction":"underground"},{"label":"哪份军令是先送来的？","reply":"“保护听证。清除命令在表决前就盖好了。”权力早已准备替失败杀人。","stance":"curiosity","flag":"n5_26_0_1","dc":16,"faction":"underground"},{"label":"你能保证新兵也可以拒绝执行吗？","reply":"凯尔当众取消连坐：不持枪不算叛逃，这一次他先承担自己的命令。","stance":"care","flag":"n5_26_0_2","dc":16,"faction":"underground"},{"label":"[说服] 请他向所有士兵读出两份军令。","reply":"凯尔逐字念完，军令矛盾不再能被藏进一个私下交易。","stance":"public","skill":"说服","dc":16,"failure":"他不敢公开读，柏戈保下副本，谈判只能让部分士兵先退到外院。","flag":"n5_26_0_3","faction":"underground"},{"label":"你守过什么样的门？","reply":"“一扇让我母亲进不来的门。”他没有拿这件事给自己无罪，只解释为什么今天还会犹豫。","stance":"curiosity","flag":"n5_26_0_4","dc":16,"faction":"underground"},{"label":"门很重，不过你未必得一直扮作门。","reply":"凯尔看着沉默的新兵，终于从门正中央退开半步。","stance":"humor","flag":"n5_26_0_5","dc":16,"faction":"underground"},{"label":"[战士] 检查开门队形，避免拒令新兵成第一排靶子。","reply":"你把拒令者安排到运伤队后方。凯尔让老兵先守住交叉火线，停止命令不再需要新兵用身体签字。","failure":"走廊过窄，队形无法完整展开。你要求先撤伤员，开门行动暂缓。","class":"战士","skill":"运动","stance":"solidarity","dc":16,"flag":"n5_class_26_0","faction":"underground"},{"label":"[游荡者] 核对侧门钥匙，防止私下交易把证人送进另一场伏击。","reply":"两把钥匙的齿口一致，锁却换过。你指出侧门只能作为核查后的撤离口，不能相信凯尔一句保证。","failure":"锁内痕迹无法辨认。你拒绝让证人先进去试路，要求有人公开检查。","class":"游荡者","skill":"调查","stance":"curiosity","dc":16,"flag":"n5_class_26_1","faction":"underground"},{"label":"[法师] 鉴别原令的权限与清除术的目标。","reply":"清除术指向名册索引，不确认当事人是否有罪。凯尔看见命令删除的包括刚抬进来的伤兵。","failure":"术式保留了反侦测层。你无法证实全部目标，只能要求暂停执行并保存原令。","class":"法师","skill":"奥秘","stance":"curiosity","dc":16,"flag":"n5_class_26_2","faction":"underground"},{"label":"[牧师] 询问凯尔愿不愿让失踪者家属来核验命令。","reply":"他没有要求家属先原谅卫队。名单被送到门外，拒令的理由开始由受影响者共同核验。","failure":"凯尔担心家属在门外遇袭。你们先安排保护，没有虚报核验已经完成。","class":"牧师","skill":"洞悉","stance":"curiosity","dc":16,"flag":"n5_class_26_3","faction":"underground"},{"label":"[游侠] 找出护卫换岗与居民撤离之间的空隙。","reply":"运药车经过时防线会松开半刻。你让居民与护卫一起清点，空隙成为公开的撤离窗口。","failure":"换岗被临时取消。你留下药车标识，不能承诺原定窗口仍安全。","class":"游侠","skill":"求生","stance":"curiosity","dc":16,"flag":"n5_class_26_4","faction":"underground"},{"label":"[吟游诗人] 把清除令逐字读给执行者，而不是替他们朗读英雄宣言。","reply":"念到伤兵也在目标里，一位老兵要来原件自己看。凯尔允许各人读完，不逼他们当场高呼倒戈。","failure":"喧声压住宣读。你把抄件交到队列，结果留待他们自行核对。","class":"吟游诗人","skill":"表演","stance":"curiosity","dc":16,"flag":"n5_class_26_5","faction":"underground"},{"label":"[圣武士] 要求拒令者和下令者都进入公开审理。","reply":"凯尔确认保护拒令者，不要求取消卫队所有旧案。门开了一道缝，审理没有被胜利情绪提前关闭。","failure":"部分护卫拒绝审理条件。凯尔只能保护愿意停手的人，无法替全队宣布免责。","class":"圣武士","skill":"说服","stance":"honesty","dc":16,"flag":"n5_class_26_6","faction":"underground"}]},{"text":"办公室传来最后通牒，要求守卫封门等待雇佣兵接管。","options":[{"label":"展示原件，要求停止矛盾命令。","reply":"卫队封住的是武装增援入口，而非听证市民的出口。","stance":"curiosity","flag":"n5_26_1_0","dc":16,"faction":"underground"},{"label":"争取守卫，写明退役与审理保障。","reply":"凯尔不要求赦免，柏戈却要求不能逼士兵假装自己从未参与。","stance":"solidarity","flag":"n5_26_1_1","dc":16,"faction":"underground"},{"label":"[威吓] 要他马上开门，否则视为继续执行清除令。","reply":"他开门，保留自己的书面异议。被逼的合作不会变成对你们的爱戴。","stance":"threat","skill":"威吓","dc":16,"failure":"新兵惊慌举枪，谈判暂停，你们必须先分开市民与守卫。","flag":"n5_26_1_2","faction":"underground"},{"label":"不等卫队同意，从侧门护送证人。","reply":"凯尔没有攻击撤离者，却也没有替你们挡住即将来的雇佣兵。","stance":"skeptic","flag":"n5_26_1_3","dc":16,"faction":"underground"}]},{"text":"新兵问只做过一次错误选择的人，有没有资格再选一次。","options":[{"label":"有。但第二次不能删除第一次。","reply":"他留名接受审理，站到市民撤离队伍旁边。","stance":"honesty","flag":"n5_26_2_0","dc":16,"faction":"underground"},{"label":"先保证他不用靠杀人证明忠诚。","reply":"凯尔将他的岗位改为运送伤者，退到门后不再意味着逃罪。","stance":"care","flag":"n5_26_2_1","dc":16,"faction":"underground"},{"label":"让柏戈保存拒令者名单。","reply":"这份记录以后能区分服从、拒绝与授意，责任不再混成一团。","stance":"curiosity","flag":"n5_26_2_2","dc":16,"faction":"underground"},{"label":"让居民代表监督守卫放行。","reply":"开门不再是两位武装者的私约，而有真实的受保护者在场。","stance":"public","flag":"n5_26_2_3","dc":16,"faction":"underground"}]}]'::jsonb),
(27,'平民代表娜芙','决战 · 让最终战的胜利意味着有人能活着说完话，而非敌人血条清空。','[{"text":"娜芙把孩子的书包按回桌下，低声说那里还有半块没吃完的饼。","options":[{"label":"先标出平民出口，再谈反攻。","reply":"阿妮让最后一批撤离者握绳，走动不用再靠看见英雄。","stance":"care","flag":"n5_27_0_0","dc":16,"faction":"underground"},{"label":"原件在哪里？副本由谁保管？","reply":"娜芙把公开保管记录递来，过去的安排终于变成现在能救命的路线。","stance":"curiosity","flag":"n5_27_0_1","dc":16,"faction":"underground"},{"label":"谁来接应最后一批？我们留下。","reply":"阿妮要求你们指定同伴替换，不允许一句留下变成另一场无人负责的牺牲。","stance":"solidarity","flag":"n5_27_0_2","dc":16,"faction":"underground"},{"label":"[威吓] 要雇佣兵停止射击孩子。","reply":"弩手迟疑，队长提醒他合同没写屠杀。雇佣关系里终于出现可分化的裂缝。","stance":"threat","skill":"威吓","dc":16,"failure":"队长让弩手更换目标，你们只能以掩体和侧门保护孩子，不能靠一句威胁结束战斗。","flag":"n5_27_0_3","faction":"underground"},{"label":"允许带人走，不向买纸的人交纸。","reply":"娜芙将原件交给两名不同派系的护卫，避免一次拦截毁掉所有证据。","stance":"honesty","flag":"n5_27_0_4","dc":16,"faction":"underground"},{"label":"阿妮，别把我们写成最后一个才能被救的人。","reply":"“放心，你们也按名单。”她在撤离册上认真加上你们。","stance":"humor","flag":"n5_27_0_5","dc":16,"faction":"underground"}]},{"text":"雇佣兵队长宣布只要交纸，这场战斗就没有发生过。","options":[{"label":"迎战并保护保管原件的队伍。","reply":"你们守的不是唯一的英雄位置，而是能让他人继续作证的通道。","stance":"solidarity","flag":"n5_27_1_0","dc":16,"faction":"underground"},{"label":"优先疏散市民，原件由副本体系补救。","reply":"你们接受资料缺损风险，不把孩子留到证据清点完才准离开。","stance":"care","flag":"n5_27_1_1","dc":16,"faction":"underground"},{"label":"[说服] 让雇佣兵接受有见证的撤退。","reply":"部分佣兵交出合同，他们仍可能受审，但不用为了旧雇主继续杀人。","stance":"public","skill":"说服","dc":16,"failure":"队长撕毁合同，部下保留碎页。谈判没成功，雇主的付款证据却没有随他说法消失。","flag":"n5_27_1_2","faction":"underground"},{"label":"交出假原件，诱队长离开市民出口。","reply":"副本的价值再次取决于此前是否准备，临场谎言并非凭空变出证据。","stance":"deception","flag":"n5_27_1_3","dc":16,"faction":"underground"}]},{"text":"孩子问桌子外面是否已经安全，没人愿意先说保证。","options":[{"label":"陪他一起确认，不叫他自己勇敢。","reply":"娜芙带他看真实的出口，安全不再只是大人一句漂亮的话。","stance":"care","flag":"n5_27_2_0","dc":16,"faction":"underground"},{"label":"先读撤离名单，找齐仍未到场的人。","reply":"阿妮没有把人数相同当作每个人都回来。","stance":"curiosity","flag":"n5_27_2_1","dc":16,"faction":"underground"},{"label":"允许敌方伤者接受治疗与拘留。","reply":"胜利没有变成不需审理的复仇，雇佣合同得以继续追查。","stance":"honesty","flag":"n5_27_2_2","dc":16,"faction":"underground"},{"label":"当众记录谁留下、谁撤离、谁曾拒绝开门。","reply":"功劳与责任一起进入判决，不再只有一张胜利插画。","stance":"public","flag":"n5_27_2_3","dc":16,"faction":"underground"}]}]'::jsonb),
(28,'书记员罗温','判决 · 选择一种真实制度，并让英雄也受它约束。','[{"text":"罗温问：记录要不要省去你们失手和说谎的部分？","options":[{"label":"不省。按记下的事实读。","reply":"他把威胁与救援一起念出。你们的功劳没有被否定，也没有吞掉其他人的痛。","stance":"honesty","flag":"n5_28_0_0","dc":16,"faction":"underground"},{"label":"先允许受影响者纠正记录。","reply":"欧拉指出一处地址差错，罗温立刻改正，并保留更正痕迹。","stance":"care","flag":"n5_28_0_1","dc":16,"faction":"underground"},{"label":"国家制度与个案审理分开表决。","reply":"法官与埃弗没有被制度选择自动赦免，居民也不用靠定罪才能获得席位。","stance":"curiosity","flag":"n5_28_0_2","dc":16,"faction":"underground"},{"label":"[说服] 要求租户、地下人与拒令士兵都可旁听。","reply":"大厅增设座位，听证从胜者的名单扩大到受决定影响的人。","stance":"public","skill":"说服","dc":16,"failure":"部分代表退席。罗温记录反对，不虚报全体到场，表决仍可依法继续。","flag":"n5_28_0_3","faction":"underground"},{"label":"等赔偿方案明确再宣布胜利。","reply":"财产与医疗清单摆上桌，制度不再只用名字让人满意。","stance":"solidarity","flag":"n5_28_0_4","dc":16,"faction":"underground"},{"label":"英雄能不能先坐下？站着太像在逼供。","reply":"罗温搬来阿黛那种矮板凳，台下有人认出，紧绷的声音第一次缓了一点。","stance":"humor","flag":"n5_28_0_5","dc":16,"faction":"underground"}]},{"text":"议会重建、地下自治、有限改革与公开新约被放到同一张表上。","options":[{"label":"议会重建必须包含租户与被删户。","reply":"欧拉要求把资格写入正文，不能只放在庆祝词里。","stance":"public","flag":"n5_28_1_0","dc":16,"faction":"underground"},{"label":"自治必须保留医疗与跨河通行。","reply":"萨雅要求地上不能以独立为由拒绝补药，自治也须接受监督。","stance":"care","flag":"n5_28_1_1","dc":16,"faction":"underground"},{"label":"有限改革必须有失效与复核期限。","reply":"露佩写下首次复核日，改革者不再只承诺以后会更好。","stance":"honesty","flag":"n5_28_1_2","dc":16,"faction":"underground"},{"label":"另立共同新约，各地有权拒绝替他人继承债务。","reply":"希尔逐条核验，签名需要明确同意，旧契约的背面不再能偷偷回来。","stance":"solidarity","flag":"n5_28_1_3","dc":16,"faction":"underground"}]},{"text":"罗温停在最后一个空格：应否给你们免受追究的英雄身份。","options":[{"label":"不要。接受与其他人相同的规则。","reply":"记录没有给你们留一扇私人侧门。","stance":"honesty","flag":"n5_28_2_0","dc":16,"faction":"underground"},{"label":"只保留被报复时的公开保护，不免除责任。","reply":"欧拉补上所有证人都享有的同款保障，英雄不再是特权的理由。","stance":"care","flag":"n5_28_2_1","dc":16,"faction":"underground"},{"label":"请居民决定，不参与这项表决。","reply":"你们退到旁听席，第一次真正允许别人选择你们的未来。","stance":"public","flag":"n5_28_2_2","dc":16,"faction":"underground"},{"label":"先公开所有待兑现承诺，再谈奖励。","reply":"罗温建立未结事项清单，黎明不是所有任务被强行划成完成。","stance":"solidarity","flag":"n5_28_2_3","dc":16,"faction":"underground"}]}]'::jsonb),
(29,'伊莱娅·维恩','后日谈 · 为改变后的生活作出最后选择，而不是替所有人宣布从此幸福。','[{"text":"伊莱娅展开编年史，问这本书最后一页要写胜利还是未完。","options":[{"label":"写未完，留下仍待兑现的承诺。","reply":"她在结尾附上居民名录，故事不再只在你们离开时结束。","stance":"honesty","flag":"n5_29_0_0","dc":16,"faction":"underground"},{"label":"把每个曾经反对我们的人也写进去。","reply":"弗莱多印了一版异议，英雄的书不再要求全城扮成同伴。","stance":"public","flag":"n5_29_0_1","dc":16,"faction":"underground"},{"label":"先看哈罗，他还在门楼吗？","reply":"“在。他今晚值班后会回家。”伊莱娅没有把他的失去改写成彻底释怀。","stance":"care","flag":"n5_29_0_2","dc":16,"faction":"underground"},{"label":"[洞悉] 问她是否还有没对我们说的话。","reply":"她承认曾考虑把你们的失误删掉，也感谢你们最后没要求她这样做。","stance":"honesty","skill":"洞悉","dc":16,"failure":"她暂时不愿谈。你们尊重界限，编年史保留她以后增写的空页。","flag":"n5_29_0_3","faction":"underground"},{"label":"我们的酬劳什么时候付？","reply":"她递来真实账单与约定金额。报酬不再被当作破坏英雄气氛的问题。","stance":"bargain","flag":"n5_29_0_4","dc":16,"faction":"underground"},{"label":"这回马车里能不能只放行李？","reply":"弗莱在报纸上画了十三只普通箱子，第一次不用给一幅画添悼念。","stance":"humor","flag":"n5_29_0_5","dc":16,"faction":"underground"}]},{"text":"城里有四封邀请：修复街区、监督听证、沿河救援，以及没有目的地的车票。","options":[{"label":"留在城里修复街区，不领取永久职位。","reply":"阿黛给你们一张轮值表，第一项是搬木板，没人为它安排胜利乐章。","stance":"solidarity","flag":"n5_29_1_0","dc":16,"faction":"underground"},{"label":"沿河继续寻找被删姓名的人。","reply":"萨雅交来新面具，要求先问每个人愿不愿意被写回旧姓。","stance":"care","flag":"n5_29_1_1","dc":16,"faction":"underground"},{"label":"离城，让居民自己继续运转制度。","reply":"露佩接受告别，只留下承诺到期的通信地址。","stance":"honesty","flag":"n5_29_1_2","dc":16,"faction":"underground"},{"label":"留下监督席，允许居民随时撤回授权。","reply":"法伊把撤回办法印在邀请背面，不将信任写成永远。","stance":"public","flag":"n5_29_1_3","dc":16,"faction":"underground"}]},{"text":"空椅上放着一张没有署名的纸。这次它没有要求你们回答。","options":[{"label":"把纸留空，给下一位乘客自己选择。","reply":"你们关上车门，世界没有因无人签字而崩塌。","stance":"honesty","flag":"n5_29_2_0","dc":16,"faction":"underground"},{"label":"写下愿意帮忙的地址，不替陌生人作承诺。","reply":"门楼多了一条真实联系，没有附带姓名抵押。","stance":"care","flag":"n5_29_2_1","dc":16,"faction":"underground"},{"label":"带一份编年史离开，原件留在城里。","reply":"伊莱娅把复本交来，居民仍拥有更正自己故事的权利。","stance":"public","flag":"n5_29_2_2","dc":16,"faction":"underground"},{"label":"再去街上走一遍，看看承诺在哪一扇门前。","reply":"黎明之后仍有可探索的街道，不再只有结局面板里的赞词。","stance":"solidarity","flag":"n5_29_2_3","dc":16,"faction":"underground"}]}]'::jsonb)
on conflict(chapter_id) do update set speaker=excluded.speaker,role=excluded.role,beats=excluded.beats;
update public.campaign_chapters set choices='[{"label":"追查车底灰烬，保留真实车册","clue":"询问守门人","flag":"ash","outcome":"原始车册留下；马车背后的人会知道有人在核查第十三次通行。"},{"label":"走侧门追车，先撤走门楼的人","flag":"gate","outcome":"门楼的人先撤离；你们放弃当场封车，把追查转入城内。"},{"flag":"n5_choice_0_2","label":"封住车厢并请街坊见证","outcome":"街坊成为共同见证人；追查者无法只向一个守门人施压。"},{"flag":"n5_choice_0_3","label":"把空椅子交给哈罗，保住他的证词","outcome":"空椅与证词分开保管；哈罗承担保管责任而不是替你们作战。"}]'::jsonb where id=0;
update public.campaign_chapters set choices='[{"label":"打开铜匣并追查匿名汇票","clue":"铜匣密码","flag":"cipher","outcome":"匣内材料进入调查；艾尔必须面对当年的寄存记录。"},{"label":"护送艾尔离开，把名单藏入账册","flag":"keeper","outcome":"艾尔得到撤离安排；名单暂不进入公开档案。"},{"flag":"n5_choice_1_2","label":"用空匣诱出白手套的买家","outcome":"买家见到的是空匣；你们承担诱饵被识破的风险。"},{"flag":"n5_choice_1_3","label":"将寄存账公开，接受被追查的风险","outcome":"寄存铺不再能置身事外；居民可以核对自己的寄存记录。"}]'::jsonb where id=1;
update public.campaign_chapters set choices='[{"label":"破解灯号，留下真实的救援地址","clue":"隐秘会面","flag":"signal","outcome":"求救地址保持真实；追兵也有可能读到同一组灯号。"},{"label":"护送诺娅与她弟弟脱离追猎","flag":"courier","outcome":"诺娅先把弟弟带走；她不再独自留在屋顶发信。"},{"flag":"n5_choice_2_2","label":"架设救援绳索，让更多无名者逃走","outcome":"绳索留给后来的人；救援范围超过这对姐弟。"},{"flag":"n5_choice_2_3","label":"用假灯号将追猎者引向废塔","outcome":"废塔成为追猎目标；原求救路线暂时隐去。"}]'::jsonb where id=2;
update public.campaign_chapters set choices='[{"label":"核对座次，追查代签请柬的人","clue":"缺席的主人","flag":"absence","outcome":"座次与代签者继续被核验；宴会的体面无法盖住空位。"},{"label":"安置宾客与孩子，带伊莱娅离开","flag":"trust","outcome":"宾客先被转移；伊莱娅不必独自面对追问。"},{"flag":"n5_choice_3_2","label":"当众揭穿空椅上的假主人","outcome":"假主人遭到公开质疑；在场宾客共同承担作证压力。"},{"flag":"n5_choice_3_3","label":"保留假宴会，诱使冒名者现身","outcome":"宴会继续；你们暂缓揭穿，以换取冒名者露面的机会。"}]'::jsonb where id=3;
update public.campaign_chapters set choices='[{"label":"带走真图，追查二十七笔交易","clue":"地契地图","flag":"map","outcome":"地图进入证据链；二十七笔交易须逐项核对。"},{"label":"留下假图，给被卖住户争取一晚","flag":"decoy","outcome":"买家暂时得到假图；住户多一晚准备，却没有永久保障。"},{"flag":"n5_choice_4_2","label":"公开售地图，让居民共同撤回交付","outcome":"居民获得知情机会；你们无法替他们撤回所有授权。"},{"flag":"n5_choice_4_3","label":"让赛芙签下证词，保留井房撤离口","outcome":"赛芙的证词被保留；井房作为撤离路线而不是毁证出口。"}]'::jsonb where id=4;
update public.campaign_chapters set choices='[{"label":"抄录护送费，保留工人的工资凭据","clue":"灰市账目","flag":"ledger","outcome":"工资与护送费被分开记录；工人不替穆雷承担假账责任。"},{"label":"匿名保护工人，追查扣押姓名的买家","flag":"workers","outcome":"工人暂不公开姓名；他们自己决定何时出面。"},{"flag":"n5_choice_5_2","label":"公开假账，让穆雷承担自己的责任","outcome":"穆雷无法靠救过人免除责任；公开账目也可能招来报复。"},{"flag":"n5_choice_5_3","label":"调换账本，跟踪收账人的下一站","outcome":"假账替换原件；你们继续追踪，不把骗局当成调查结论。"}]'::jsonb where id=5;
update public.campaign_chapters set choices='[{"label":"封存白蕨与废液，追查盐井来源","clue":"矿坑孢子","flag":"spore","outcome":"样本被封存；花房与盐井的供应关系仍须证实。"},{"label":"保护学徒，带桶牌离开花房","flag":"gardener","outcome":"学徒先离开污染区；桶牌保留供后续核验。"},{"flag":"n5_choice_6_2","label":"焚毁模仿声音的白蕨并封住毒水","outcome":"白蕨与毒水通路被处理；可重复检测的活体材料减少。"},{"flag":"n5_choice_6_3","label":"公开送货编号，逼维护处回应","outcome":"维护处收到公开质询；居民能核对送货编号。"}]'::jsonb where id=6;
update public.campaign_chapters set choices='[{"label":"核对原版，追查修改遗言的付款人","clue":"篡改的信","flag":"letters","outcome":"三份原版留下；修改者的付款链继续追查。"},{"label":"刊出一封保护家属的求救信","flag":"publicity","outcome":"家属身份得到遮掩；读者暂时看不到完整矛盾。"},{"flag":"n5_choice_7_2","label":"三信并刊，公开全部改动痕迹","outcome":"三份遗言同时公布；家属与报社都面临公众追问。"},{"flag":"n5_choice_7_3","label":"停机撤离，保住报社人与原件","outcome":"机器停下；原件与编辑撤离，出版被延后。"}]'::jsonb where id=7;
update public.campaign_chapters set choices='[{"label":"查清假巡逻队与同号军令","clue":"巡逻证词","flag":"patrol","outcome":"军令与制服被分别核对；相同编号不能单独证明士兵有罪。"},{"label":"保护被诬士兵，安排匿名撤离","flag":"bribe","outcome":"被诬士兵先撤离；公开澄清被推迟。"},{"flag":"n5_choice_8_2","label":"接受维斯自首，交换父女自由","outcome":"维斯的自首被记录；女儿不会作为他的罪责担保。"},{"flag":"n5_choice_8_3","label":"让街坊共同核验拘捕令","outcome":"拘捕令交由街坊核验；卫队失去独自解释命令的权力。"}]'::jsonb where id=8;
update public.campaign_chapters set choices='[{"label":"拓印裂章，依法挑战伪地契","clue":"议会印记","flag":"seal","outcome":"真章被保存；法律挑战不等于承认旧驱逐正当。"},{"label":"向街坊公开证据与调查限制","flag":"neighbours","outcome":"街坊知道已有与缺失的证据；不会收到虚假的安全保证。"},{"flag":"n5_choice_9_2","label":"拆下旧碑，保存被驱逐者姓名","outcome":"碑上姓名进入保管记录；拆碑本身不能取消地契。"},{"flag":"n5_choice_9_3","label":"组建居民保管组，共同护送证据","outcome":"居民共同保管原件；你们不再是唯一能够决定公开的人。"}]'::jsonb where id=9;
update public.campaign_chapters set choices='[{"label":"潜入拍卖后台，取得保证金账户","clue":"拍卖名单","flag":"auction","outcome":"保证金账户进入追查；幕后担保人暂时未被惊动。"},{"label":"拖延买家，安排拍品持有人撤离","flag":"buyer","outcome":"持有人先撤离；交易争议留待后续处理。"},{"flag":"n5_choice_10_2","label":"当众终止姓名拍卖并公开规则","outcome":"拍卖规则遭公开挑战；受害者不必以买家身份赎回姓名。"},{"flag":"n5_choice_10_3","label":"假装成交，跟踪真正付款者","outcome":"付款链继续暴露；你们不得把假成交当成真实授权。"}]'::jsonb where id=10;
update public.campaign_chapters set choices='[{"label":"拆解齿箱，保住契约原件","clue":"齿轮暗格","flag":"gear","outcome":"原件取出；承压问题必须由后续维修承担。"},{"label":"安置格雷与井下居民，重做承压","flag":"warden","outcome":"居民先离开危险区；格雷参与重做承压方案。"},{"flag":"n5_choice_11_2","label":"开放备用发条，终止临时牺牲","outcome":"备用发条投入方案；井下居民不再被默认为耗材。"},{"flag":"n5_choice_11_3","label":"留下原件运行，用多份抄本取证","outcome":"原件暂时留在运行机构；多份抄本分散证据风险。"}]'::jsonb where id=11;
update public.campaign_chapters set choices='[{"label":"修复名册与选票，保留签名批注","clue":"旧城选票","flag":"ballots","outcome":"名册与批注一起保存；馆藏不会替签字者隐去责任。"},{"label":"开放档案，允许地下居民核验","flag":"archive","outcome":"档案开放核验；地下居民能够提出自己的更正。"},{"flag":"n5_choice_12_2","label":"公开埃弗责任，拒绝有条件的资助","outcome":"埃弗的责任被公开；附带隐瞒条件的资助被拒绝。"},{"flag":"n5_choice_12_3","label":"护送馆员撤离，延后公开但保留原件","outcome":"馆员与原件先撤离；公众阅读受到延迟。"}]'::jsonb where id=12;
update public.campaign_chapters set choices='[{"label":"追踪白鸦，同时组织船坞救援","clue":"信使路线","flag":"raven","outcome":"送信与救援同时推进；队伍需要承担两处保护责任。"},{"label":"优先营救菲恩家属，保留旧信","flag":"handler","outcome":"家属优先获救；白鸦的消息不会替救援报功。"},{"flag":"n5_choice_13_2","label":"送出假地址，引开截信追兵","outcome":"追兵被引向假地址；你们必须防止无关住户受牵连。"},{"flag":"n5_choice_13_3","label":"公开截信事实，安排收信人保护","outcome":"截信被公开；收信人的保护安排也要接受核验。"}]'::jsonb where id=13;
update public.campaign_chapters set choices='[{"label":"核对错位日期，挑战旧印的新授权","clue":"错位日期","flag":"dates","outcome":"旧印的新用法被挑战；日期矛盾进入正式记录。"},{"label":"公开迁居令矛盾，保护基层证人","flag":"expose","outcome":"基层证人得到保护；迁居命令的冲突被公开。"},{"flag":"n5_choice_14_2","label":"封存行政印章，阻止下一批迁居","outcome":"印章停止签发新令；已有迁居案仍须逐户处理。"},{"flag":"n5_choice_14_3","label":"组织被迁居民共同核验原件","outcome":"被迁居民参与核验；他们可以指出档案遗漏。"}]'::jsonb where id=14;
update public.campaign_chapters set choices='[{"label":"分享自己的经历，交换匿名口述","clue":"无名者口述","flag":"testimony","outcome":"交换以自愿口述进行；没有人需要交出法定姓名。"},{"label":"带药并参与居民撤离","flag":"medicine","outcome":"药品与撤离优先；援助不以证词交换为条件。"},{"flag":"n5_choice_15_2","label":"分散保管面具，保护街区记忆","outcome":"面具分散保管；一个保管者失守不再抹去整条街。"},{"flag":"n5_choice_15_3","label":"组织公开援助，但不公开藏身处","outcome":"援助用途公开；藏身处保持秘密以免引来追捕。"}]'::jsonb where id=15;
update public.campaign_chapters set choices='[{"label":"取得饮水原令与炼金样本","clue":"炼金徽章","flag":"alchemist","outcome":"水令与样本同时保留；疾病不会被归作士兵天性。"},{"label":"优先救助伤兵并安排治疗","flag":"rescued","outcome":"治疗先开始；伤兵是否作证由他们康复后决定。"},{"flag":"n5_choice_16_2","label":"公开烧柜令，拒绝毁证换药","outcome":"烧柜命令公开；毁证不再成为取得药物的条件。"},{"flag":"n5_choice_16_3","label":"组织家属参与转移与监督","outcome":"家属参与转移；军医的安排受到现场监督。"}]'::jsonb where id=16;
update public.campaign_chapters set choices='[{"label":"备战并封住废液闸门","clue":"甲壳残片","flag":"shell","outcome":"废液闸门列入控制目标；击败野兽不能替代污染治理。"},{"label":"沿检修路绕行，保留兽与饲养证词","flag":"bypass","outcome":"检修路成为通行方案；野兽与饲养者的关系保留调查。"},{"flag":"n5_choice_17_2","label":"切断钟响灌注，争取安静通行","outcome":"灌注被列入切断方案；通行不再只靠杀死拦路者。"},{"flag":"n5_choice_17_3","label":"保护矿工撤离，再追查毒液责任人","outcome":"矿工先撤离；毒液责任不能随战斗胜利被遗忘。"}]'::jsonb where id=17;
update public.campaign_chapters set choices='[{"label":"保护原告，取得包含法官责任的案卷","clue":"驱逐案卷","flag":"verdict","outcome":"案卷包含法官的签字；保护原告不等于替法官免责。"},{"label":"交换地下护卫，分散证人撤离","flag":"witness","outcome":"证人分散撤离；地下护卫的责任与期限被记录。"},{"flag":"n5_choice_18_2","label":"要求法官公开自证并留下掩护","outcome":"法官留下公开说明；他不能要求原告先表示感谢。"},{"flag":"n5_choice_18_3","label":"分别保管控罪证据与撤离名单","outcome":"控罪材料与撤离名单分开；持有证据不等于知道藏身处。"}]'::jsonb where id=18;
update public.campaign_chapters set choices='[{"label":"质询埃弗，追究售地与焚证","clue":"议员供词","flag":"confession","outcome":"售地与焚证被追问；失踪经历不能消除埃弗的责任。"},{"label":"给予受保护的作证机会，不承诺赦免","flag":"mercy","outcome":"埃弗可以作证；保护承诺不包含赦免。"},{"flag":"n5_choice_19_2","label":"公开供词与责任，保护孩子隐私","outcome":"公众知道供词与罪责；孩子的身份不随案情一起曝光。"},{"flag":"n5_choice_19_3","label":"拒绝权限交易，靠独立证据继续调查","outcome":"调查继续依靠独立材料；埃弗不能出售最后一份授权。"}]'::jsonb where id=19;
update public.campaign_chapters set choices='[{"label":"封锁长廊，核验真实刺客线索","clue":"镜厅脚印","flag":"mirror","outcome":"长廊封锁；真实袭击须经核验，倒影不能作为定罪证据。"},{"label":"保护证人撤离，不先追杀倒影","flag":"protected","outcome":"证人先撤离；追杀可疑倒影被搁置。"},{"flag":"n5_choice_20_2","label":"调转镜轴，揭穿假未来","outcome":"镜轴的操纵被暴露；所谓未来不再自动取得权威。"},{"flag":"n5_choice_20_3","label":"让护卫扮演假背叛，诱刺客出手","outcome":"护卫协助诱敌；假背叛不会被登记成真实供词。"}]'::jsonb where id=20;
update public.campaign_chapters set choices='[{"label":"潜入办公室，取得停钟原令","clue":"停钟命令","flag":"order","outcome":"原令进入证据链；停钟理由不能只由办公室口头解释。"},{"label":"迫使改革派公开复钟条件","flag":"reform","outcome":"改革派公开条件；居民能指出谁仍要付出代价。"},{"flag":"n5_choice_21_2","label":"推行不以姓名供能的发条改造","outcome":"替代能源进入实施议程；居民姓名不再被默认为燃料。"},{"flag":"n5_choice_21_3","label":"限时复钟抢救危户，记录未解除名单","outcome":"复钟限定救援期限；未解除的姓名债继续公开记录。"}]'::jsonb where id=21;
update public.campaign_chapters set choices='[{"label":"核验封桥令，谈判公开通行","clue":"封桥令","flag":"bridge","outcome":"通行条件公开谈判；迁居令不能伪装成救援车辆名单。"},{"label":"请求旧盟友，护送证人过检修道","flag":"allies","outcome":"旧盟友参与护送；他们有权拒绝超出承诺的风险。"},{"flag":"n5_choice_22_2","label":"让双方共同查车，分开处理救援与迁居","outcome":"双方共同检查车辆；伤者与迁居对象分开登记。"},{"flag":"n5_choice_22_3","label":"公开命令，建立居民与卫队的共同通道","outcome":"居民与卫队共同管理通道；没有一方独占核验权。"}]'::jsonb where id=22;
update public.campaign_chapters set choices='[{"label":"组织守卫止火并保护档案","clue":"纵火工具","flag":"arson","outcome":"火线与档案同时防守；守卫要给被困者保留出口。"},{"label":"先救馆员与孩子，接受原件受损","flag":"librarians","outcome":"人先离开；档案缺损公开记录，不虚报全部保全。"},{"flag":"n5_choice_23_2","label":"切断油路，协调两端同步撤离","outcome":"油路列入切断目标；两端撤离时间需要现场协调。"},{"flag":"n5_choice_23_3","label":"用水保全残页，公开档案缺损","outcome":"残页经过抢救与登记；缺失页不会被后来的英雄故事补写。"}]'::jsonb where id=23;
update public.campaign_chapters set choices='[{"label":"收集各派条件，保障租户与地下席位","clue":"各派条件","flag":"factions","outcome":"各派条件进入同一记录；租户与地下居民拥有席位。"},{"label":"举行公开集会，保留不同意见","flag":"assembly","outcome":"反对意见也进入公开集会；赞同英雄不作为入场条件。"},{"flag":"n5_choice_24_2","label":"先签医疗与撤离公约，再议制度","outcome":"医疗与撤离先获保障；制度争议不再扣住急需的药物。"},{"flag":"n5_choice_24_3","label":"建立可撤回授权，拒绝英雄终身席","outcome":"授权可以撤回；英雄没有自动得到终身席位。"}]'::jsonb where id=24;
update public.campaign_chapters set choices='[{"label":"鉴定完整契约，公开它的旧罪","clue":"原始契约","flag":"contract","outcome":"契约全文与旧罪公开；鞋匠的签字不会被当成城市同意。"},{"label":"邀请各派核验，另立共同新约","flag":"unity","outcome":"新约需要各方明确同意；旧债不能偷偷转入签名背面。"},{"flag":"n5_choice_25_2","label":"废止旧约，保留证物并取消继承抵押","outcome":"旧约提出废止；证物保存供追责，居民不继承姓名抵押。"},{"flag":"n5_choice_25_3","label":"居民共管原件，分别签署真实责任","outcome":"居民共同保管；各人承担的是明示责任而不是连带旧债。"}]'::jsonb where id=25;
update public.campaign_chapters set choices='[{"label":"展示原件，要求卫队停止清除令","clue":"矛盾命令","flag":"guard","outcome":"卫队收到原件核验要求；停止清除令成为进入议程的前提。"},{"label":"争取守卫放下武器并接受审理","flag":"defector","outcome":"拒令守卫获得作证保护；他们仍接受责任审理。"},{"flag":"n5_choice_26_2","label":"居民监督开门，保护拒令的新兵","outcome":"居民监督开门；新兵不会被要求靠杀同袍证明忠诚。"},{"flag":"n5_choice_26_3","label":"从侧门撤离证人，拒绝私人军令交易","outcome":"证人从侧门撤离；私人交易不能换取军令合法化。"}]'::jsonb where id=26;
update public.campaign_chapters set choices='[{"label":"迎战雇佣兵，守住证据与出口","clue":"雇佣契约","flag":"mercenary","outcome":"队伍承担守住出口的责任；市民不作为挡箭牌。"},{"label":"优先疏散市民，接受原件缺损","flag":"civilians","outcome":"撤离优先；原件缺损成为战后必须补证的问题。"},{"flag":"n5_choice_27_2","label":"争取有见证的停战，取得雇佣合同","outcome":"停战由见证人记录；雇佣合同留下供追查付款人。"},{"flag":"n5_choice_27_3","label":"用假原件引开队长，保护最后一批撤离","outcome":"队长被引离撤离路线；假原件不能混入正式档案。"}]'::jsonb where id=27;
update public.campaign_chapters set choices='[{"label":"重建包含被删户与租户的公民议会","clue":"公民议会","flag":"council","outcome":"公民议会重建：被删户与租户纳入制度；资格不再只由业主决定。"},{"label":"建立有医疗与通行保障的地下自治","flag":"autonomy","outcome":"地下自治联盟：自治保留医疗、跨河通行与公开监督。"},{"flag":"n5_choice_28_2","label":"实行有复核期限与公开监督的有限改革","outcome":"限期监督改革：权力保留复核期限；改革承诺需接受公开检查。"},{"flag":"n5_choice_28_3","label":"废止旧约，缔结各区共同承担的新约","outcome":"各区共同新约：废止姓名抵押，各区以明示同意承担新责任。"}]'::jsonb where id=28;
update public.campaign_chapters set choices='[{"label":"记录完整后日谈，留下待履行承诺","clue":"队伍编年史","flag":"epilogue","outcome":"编年史保存功劳与过失；未履行承诺留作公开清单。"},{"label":"继续自由探索，参与街区修复","flag":"legacy","outcome":"自由探索继续；街区修复不会被通关庆典自动算作完成。"},{"flag":"n5_choice_29_2","label":"离城，把原件与制度留给居民","outcome":"居民保管制度与原件；队伍离城不取消他们更正历史的权利。"},{"flag":"n5_choice_29_3","label":"沿河寻找更多失名者，保留联系","outcome":"队伍沿河寻找失名者；城内联系人保留独立作决定的权利。"}]'::jsonb where id=29;
